{
  "_note": "Stop hook auto-runs cost-track at session end so the cost-tracking namespace stays populated without users remembering to run `/cost-track` manually. TRACK_QUIET=1 suppresses the markdown summary (avoid spamming on every Stop). `|| true` ensures a track failure NEVER blocks session end — analytics data is best-effort, not load-bearing.",
  "_platform": "posix",
  "_platform_note": "POSIX hooks (bash + node). Windows users continue to invoke `cost-track` manually via the slash command (the Stop hook silently no-ops on a non-bash shell).",
  "hooks": {
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "/bin/bash -c 'TRACK_QUIET=1 node \"${CLAUDE_PLUGIN_ROOT}/scripts/track.mjs\" >/dev/null 2>&1 || true'"
          }
        ]
      }
    ]
  }
}

import { spawnSync } from 'node:child_process';
import { dirname, join } from 'node:path';

// Windows npm exposes npx through a .cmd shim, which cannot be spawned
// directly by Node without a shell. Invoking npm's JS entry point preserves
// argv exactly (especially JSON values) and avoids shell injection/quoting.
export function spawnNpxSync(args, options = {}) {
  const npxArgs = args[0] === '-y' ? args : ['-y', ...args];
  const { shell: _ignoredShell, ...safeOptions } = options;
  if (process.platform === 'win32') {
    const npxCli = join(dirname(process.execPath), 'node_modules', 'npm', 'bin', 'npx-cli.js');
    return spawnSync(process.execPath, [npxCli, ...npxArgs], { ...safeOptions, shell: false });
  }
  return spawnSync('npx', npxArgs, { ...safeOptions, shell: false });
}

// _prices.mjs — single source of truth for cost-tracker model pricing.
//
// Iter 31 of ADR-149 router work consolidated 5 scripts' worth of pricing
// into one module. This is the cost-tracker plugin equivalent: track.mjs
// and counterfactual.mjs both maintained identical PRICING tables, and
// bench.mjs has its own ANTHROPIC_PRICING. When pricing changes, drift
// across scripts is the failure mode. One module prevents that.
//
// Underscore-prefix filename signals "library, not a CLI entry" — smoke.sh
// uses `scripts/*.mjs` for the CLI surface check, but reaches this file
// only through the `parses cleanly` step (still valid).

// USD per 1M tokens. Kept in sync with REFERENCE.md "Model pricing" table.
// Source of truth for: track.mjs (session cost computation),
// counterfactual.mjs (multi-baseline analysis), bench.mjs (anthropic baseline).
export const PRICING = {
  haiku:  { input: 0.25,  output: 1.25,  cache_write: 0.30,  cache_read: 0.03 },
  sonnet: { input: 3.00,  output: 15.00, cache_write: 3.75,  cache_read: 0.30 },
  opus:   { input: 15.00, output: 75.00, cache_write: 18.75, cache_read: 1.50 },
};

/** Map a model id to one of `haiku | sonnet | opus | unknown`. */
export function modelTier(model) {
  if (!model) return 'unknown';
  const m = String(model).toLowerCase();
  if (m.includes('haiku')) return 'haiku';
  if (m.includes('sonnet')) return 'sonnet';
  if (m.includes('opus')) return 'opus';
  return 'unknown';
}

/**
 * Compute USD cost for a usage record at a given tier.
 * usage: { input_tokens, output_tokens, cache_creation_input_tokens, cache_read_input_tokens }
 */
export function costForUsage(tier, usage) {
  const p = PRICING[tier];
  if (!p || !usage) return 0;
  return (usage.input_tokens || 0) / 1e6 * p.input
       + (usage.output_tokens || 0) / 1e6 * p.output
       + (usage.cache_creation_input_tokens || 0) / 1e6 * p.cache_write
       + (usage.cache_read_input_tokens || 0) / 1e6 * p.cache_read;
}

/**
 * Compute USD cost for a tokens-bundle (totals already summed) at a given tier.
 * tokens: { input, output, cache_write, cache_read }
 * Used by counterfactual analysis where tokens are aggregated across models
 * before applying a single baseline tier's pricing.
 */
export function costAtTier(tokens, tier) {
  const p = PRICING[tier];
  if (!p) return 0;
  return (tokens.input / 1e6) * p.input
       + (tokens.output / 1e6) * p.output
       + (tokens.cache_write / 1e6) * p.cache_write
       + (tokens.cache_read / 1e6) * p.cache_read;
}

// _sessions.mjs — shared session-loader for the cost-tracking namespace.
//
// Iter 73 consolidation. Six analytics scripts (anomaly, burn, conversation,
// counterfactual, projection, budget) previously duplicated identical
// boilerplate for reading sessions from the `cost-tracking` namespace.
// This module is the single source of truth. Math is byte-identical to
// the per-script copies it replaces.
//
// CONTRACT
//   - `memoryListSessionKeys(ns)`      → keys starting with `session-` only
//   - `memoryListAllKeys(ns)`          → ALL keys in namespace (for non-session lookups)
//   - `memoryRetrieve(ns, key)`        → parsed JSON value, or null on failure
//   - `loadSessions(ns)`               → array of session records (filters out nulls)
//   - `sessionTs(rec)`                 → ms-since-epoch from capturedAt|endedAt|startedAt
//   - `parseDurationMs(spec)`          → ms for "Nh"/"Nd"/"Nw"/"Nm"; null on parse fail

import { spawnNpxSync } from './_npx.mjs';

const CLI_PKG = process.env.CLI_CORE === '1'
  ? '@claude-flow/cli-core@alpha'
  : '@claude-flow/cli@latest';

export function memoryListAllKeys(namespace) {
  const r = spawnNpxSync([
    CLI_PKG, 'memory', 'list',
    '--namespace', namespace, '--format', 'json',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) return [];
  const m = /\[[\s\S]*\]/.exec(r.stdout || '');
  if (!m) return [];
  let entries;
  try { entries = JSON.parse(m[0]); } catch { return []; }
  return entries
    .map((e) => e.key)
    .filter((k) => typeof k === 'string');
}

export function memoryListSessionKeys(namespace) {
  return memoryListAllKeys(namespace).filter((k) => k.startsWith('session-'));
}

export function memoryRetrieve(namespace, key) {
  const r = spawnNpxSync([
    CLI_PKG, 'memory', 'retrieve',
    '--namespace', namespace, '--key', key, '--value-only',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) return null;
  try { return JSON.parse((r.stdout || '').trim()); } catch { return null; }
}

export function loadSessions(namespace) {
  const keys = memoryListSessionKeys(namespace);
  const records = [];
  for (const k of keys) {
    const rec = memoryRetrieve(namespace, k);
    if (rec) records.push(rec);
  }
  return records;
}

export function sessionTs(rec) {
  const t = rec.capturedAt || rec.endedAt || rec.startedAt;
  return t ? new Date(t).getTime() : 0;
}

export function parseDurationMs(spec) {
  const m = /^(\d+)([hdwm])$/.exec(spec);
  if (!m) return null;
  const n = parseInt(m[1], 10);
  const unit = { h: 3600_000, d: 86400_000, w: 7 * 86400_000, m: 30 * 86400_000 }[m[2]];
  return unit ? n * unit : null;
}

#!/usr/bin/env node
// cost-anomaly — MAD-based outlier detection on session spend.
//
// cost-burn answers "is the LATEST BUCKET accelerating?" — a question about
// AGGREGATE trend. This script answers "which SPECIFIC SESSIONS are
// anomalous outliers?" — a question about INDIVIDUAL data points.
//
// METHOD
//   1. Read all `session-*` records from `cost-tracking` namespace.
//   2. Filter to `--since` window (default: all-time).
//   3. Compute median(total_cost_usd) and MAD = median(|x - median|).
//   4. Per-session modified z-score (Iglewicz-Hoaglin):
//        z = 0.6745 * (x - median) / MAD
//   5. Flag sessions with |z| > `--threshold` (default 3.5).
//
// Why MAD (median absolute deviation) and not mean+sigma:
//   - Robust to the very outliers we're hunting (a single $50 session
//     would inflate mean+sigma so badly that subsequent outliers hide).
//   - Works on small samples (n=10 is fine; mean+sigma needs n=30+).
//   - Iglewicz-Hoaglin (1993): |modified z| > 3.5 is the canonical cutoff.
//
// Pairs with:
//   - cost-burn          → "did the AGGREGATE rate spike?"
//   - cost-anomaly       → "which INDIVIDUAL sessions are outliers?" ← this
//   - cost-counterfactual → "could routing have been cheaper?"
//   - cost-projection    → "when will we hit budget?"
//
// USAGE
//   node scripts/anomaly.mjs                                # default 3.5 threshold, all-time
//   node scripts/anomaly.mjs --since 7d                     # last week only
//   node scripts/anomaly.mjs --threshold 3.0                # stricter (more outliers)
//   node scripts/anomaly.mjs --threshold 5.0                # looser (only egregious)
//   node scripts/anomaly.mjs --alert-on-outliers 1          # exit 1 if ≥1 outlier found
//   node scripts/anomaly.mjs --format json
//
// Env: ANOMALY_NAMESPACE (default cost-tracking), ANOMALY_QUIET=1.

// iter 73 — shared session-loader (was duplicated across 6 scripts).
import { loadSessions, sessionTs, parseDurationMs } from './_sessions.mjs';

const NS = process.env.ANOMALY_NAMESPACE || 'cost-tracking';

const ARGS = (() => {
  const a = { since: null, threshold: 3.5, alertOnOutliers: null, format: 'table' };
  if (process.env.ANOMALY_QUIET === '1') a.format = 'json';
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--since') a.since = process.argv[++i];
    else if (v === '--threshold') a.threshold = parseFloat(process.argv[++i]);
    else if (v === '--alert-on-outliers') a.alertOnOutliers = parseInt(process.argv[++i], 10);
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function median(sorted) {
  const n = sorted.length;
  if (n === 0) return 0;
  return n % 2 === 0
    ? (sorted[n / 2 - 1] + sorted[n / 2]) / 2
    : sorted[(n - 1) / 2];
}

function main() {
  if (!isFinite(ARGS.threshold) || ARGS.threshold <= 0) {
    console.error(`anomaly: --threshold must be > 0; got ${ARGS.threshold}`);
    process.exit(2);
  }
  if (ARGS.alertOnOutliers !== null && (!Number.isInteger(ARGS.alertOnOutliers) || ARGS.alertOnOutliers < 1)) {
    console.error(`anomaly: --alert-on-outliers must be a positive integer; got ${ARGS.alertOnOutliers}`);
    process.exit(2);
  }

  // Read + filter sessions (shared loader, iter 73).
  const records = loadSessions(NS);

  let cutoffMs = null;
  if (ARGS.since) {
    const ms = parseDurationMs(ARGS.since);
    if (!ms) {
      console.error(`anomaly: --since must be N(h|d|w|m); got "${ARGS.since}"`);
      process.exit(2);
    }
    cutoffMs = Date.now() - ms;
  }
  const filtered = cutoffMs === null
    ? records
    : records.filter((r) => sessionTs(r) >= cutoffMs);

  // Insufficient-data guard. MAD is meaningful only with ≥3 samples.
  if (filtered.length < 3) {
    const payload = {
      namespace: NS,
      filters: { since: ARGS.since, threshold: ARGS.threshold },
      sessionsConsidered: filtered.length,
      sufficient: false,
      reason: `need ≥3 sessions for MAD-based outlier detection; got ${filtered.length}`,
      outliers: [],
      stats: null,
      generatedAt: new Date().toISOString(),
    };
    if (ARGS.format === 'json') {
      console.log(JSON.stringify(payload, null, 2));
    } else {
      console.log(`# cost-anomaly${ARGS.since ? ` (since ${ARGS.since})` : ' (all-time)'}`);
      console.log('');
      console.log(`_Insufficient data: need ≥3 sessions for MAD-based outlier detection; got ${filtered.length}._`);
      console.log('');
    }
    return;
  }

  // Compute median + MAD over total_cost_usd.
  const spends = filtered.map((r) => r.total_cost_usd || 0).sort((a, b) => a - b);
  const med = median(spends);
  const absDeviations = spends.map((x) => Math.abs(x - med)).sort((a, b) => a - b);
  const mad = median(absDeviations);

  // MAD=0 means ≥50% of sessions share the exact same spend — z-score
  // collapses. Report the explainer instead of dividing by zero.
  let outliers = [];
  let madZero = false;
  if (mad === 0) {
    madZero = true;
  } else {
    for (const rec of filtered) {
      const x = rec.total_cost_usd || 0;
      const z = 0.6745 * (x - med) / mad;
      if (Math.abs(z) > ARGS.threshold) {
        outliers.push({
          sessionId: rec.sessionId || 'unknown',
          spendUsd: Math.round(x * 1e6) / 1e6,
          deviationUsd: Math.round((x - med) * 1e6) / 1e6,
          modifiedZ: Math.round(z * 1000) / 1000,
          capturedAt: rec.capturedAt || rec.endedAt || rec.startedAt || null,
          messageCount: rec.messageCount || 0,
          direction: x > med ? 'high' : 'low',
        });
      }
    }
    outliers.sort((a, b) => Math.abs(b.modifiedZ) - Math.abs(a.modifiedZ));
  }

  // Alert check.
  let alertTriggered = false;
  let alertReason = null;
  if (ARGS.alertOnOutliers !== null) {
    if (outliers.length >= ARGS.alertOnOutliers) {
      alertTriggered = true;
      alertReason = `found ${outliers.length} outlier session(s) (|modified z| > ${ARGS.threshold}); threshold was ≥${ARGS.alertOnOutliers}`;
    } else {
      alertReason = `found ${outliers.length} outlier session(s); under threshold ≥${ARGS.alertOnOutliers} — OK`;
    }
  }

  const payload = {
    namespace: NS,
    filters: { since: ARGS.since, threshold: ARGS.threshold, alertOnOutliers: ARGS.alertOnOutliers },
    sessionsConsidered: filtered.length,
    sufficient: !madZero,
    stats: {
      medianUsd: Math.round(med * 1e6) / 1e6,
      madUsd: Math.round(mad * 1e6) / 1e6,
      minUsd: Math.round(spends[0] * 1e6) / 1e6,
      maxUsd: Math.round(spends[spends.length - 1] * 1e6) / 1e6,
    },
    outliers,
    alert: ARGS.alertOnOutliers !== null ? {
      triggered: alertTriggered,
      reason: alertReason,
      thresholdOutlierCount: ARGS.alertOnOutliers,
    } : null,
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# cost-anomaly${ARGS.since ? ` (since ${ARGS.since})` : ' (all-time)'}`);
    console.log('');
    console.log(`| Metric | Value |`);
    console.log(`|---|---:|`);
    console.log(`| Sessions considered | ${filtered.length} |`);
    console.log(`| Threshold (|modified z|) | ${ARGS.threshold} (Iglewicz-Hoaglin default 3.5) |`);
    console.log(`| Median spend | $${med.toFixed(6)} |`);
    console.log(`| MAD | $${mad.toFixed(6)} |`);
    console.log(`| Min / Max | $${spends[0].toFixed(6)} / $${spends[spends.length - 1].toFixed(6)} |`);
    console.log(`| **Outliers found** | **${outliers.length}** |`);
    console.log('');
    if (madZero) {
      console.log(`_MAD is $0 — ≥50% of sessions share the exact same spend. No outliers can be computed; investigate if this is expected (e.g. all sessions captured during a dry-run)._`);
      console.log('');
    } else if (outliers.length === 0) {
      console.log(`✓ No outliers found within the |modified z| > ${ARGS.threshold} band.`);
      console.log('');
    } else {
      console.log('## Outlier sessions (sorted by |modified z| descending)');
      console.log('');
      console.log('| Session | Spend | Deviation | Modified z | Direction | Messages | Captured |');
      console.log('|---|---:|---:|---:|:---:|---:|---|');
      for (const o of outliers) {
        const sid = o.sessionId.slice(0, 8);
        const devStr = o.deviationUsd >= 0 ? `+$${o.deviationUsd.toFixed(6)}` : `-$${Math.abs(o.deviationUsd).toFixed(6)}`;
        console.log(`| \`${sid}\` | $${o.spendUsd.toFixed(6)} | ${devStr} | ${o.modifiedZ.toFixed(3)} | ${o.direction} | ${o.messageCount} | ${o.capturedAt || '—'} |`);
      }
      console.log('');
      console.log('_High-direction outliers are usually long sessions or sessions stuck in expensive tiers — investigate via `cost report` / `cost conversation`._');
      console.log('_Low-direction outliers may indicate dropped sessions, crashes, or unfinished work — verify the session completed normally._');
      console.log('');
    }
    if (alertReason !== null) {
      if (alertTriggered) {
        console.log(`⚠ **ALERT**: ${alertReason}`);
      } else {
        console.log(`✓ ${alertReason}`);
      }
      console.log('');
    }
  }

  if (alertTriggered) process.exit(1);
}

main();

#!/usr/bin/env node
// Verified-corpus benchmark for ruflo-cost-tracker.
// Runs every case in bench/booster-corpus.json through agent-booster.apply()
// and records: correctness vs. golden expected, latency, confidence, strategy.
// Output: JSON to docs/benchmarks/runs/<ISO>.json + markdown summary to stdout.
//
// Resolution: must be run from a directory where `agent-booster` resolves
// (typically anywhere under `v3/`). Run via:
//
//   ( cd v3 && node ../plugins/ruflo-cost-tracker/scripts/bench.mjs )
//
// Optional env:
//   BENCH_LLM_BASELINE=1   -- run the same corpus through Gemini 2.0 Flash (or another OpenAI-compat model)
//   BENCH_LLM_MODEL=...    -- override (default: models/gemini-2.0-flash)
//   BENCH_LLM_BASE_URL=... -- override (default: deployed ruvocal Gemini OpenAI shim)
//   BENCH_LLM_API_KEY=...  -- override (default: from gcloud secret GOOGLE_AI_API_KEY)
//   BENCH_LLM_PRICE_IN/OUT -- $/1M tokens override (default Gemini 2.0 Flash: 0.10 / 0.40)
//
//   BENCH_ANTHROPIC=1      -- run the same corpus through Anthropic claude models
//   BENCH_ANTHROPIC_MODELS=claude-sonnet-4-6,claude-opus-4-7   -- comma-separated list
//   BENCH_ANTHROPIC_API_KEY=... -- override (default: from gcloud secret ANTHROPIC_API_KEY)
//
//   BENCH_OUT=<path>       -- override output JSON path
//   BENCH_QUIET=1          -- suppress markdown summary
//
// Pricing built-in (per 1M tokens, USD): Sonnet 4.6 = 3/15, Opus 4.7 = 15/75, Haiku 4.5 = 1/5.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
import { dirname, join, resolve } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const PLUGIN_ROOT = resolve(HERE, '..');
const CORPUS = join(PLUGIN_ROOT, 'bench', 'booster-corpus.json');
const RUNS_DIR = join(PLUGIN_ROOT, 'docs', 'benchmarks', 'runs');

const norm = (s) => String(s ?? '').trim().replace(/\s+/g, ' ');
const pct = (n) => `${(n * 100).toFixed(1)}%`;
const ms = (n) => `${n.toFixed(2)}ms`;
const pcent = (arr, p) => {
  if (!arr.length) return 0;
  const sorted = [...arr].sort((a, b) => a - b);
  const idx = Math.min(sorted.length - 1, Math.floor((p / 100) * sorted.length));
  return sorted[idx];
};

async function main() {
  const corpus = JSON.parse(readFileSync(CORPUS, 'utf-8'));
  // Resolve agent-booster from process.cwd() (so users can `cd v3 && node ../...`)
  // rather than from the script's directory (which is outside v3/node_modules).
  let AgentBoosterMod;
  try {
    const requireFromCwd = createRequire(join(process.cwd(), 'package.json'));
    const resolvedPath = requireFromCwd.resolve('agent-booster');
    AgentBoosterMod = await import(pathToFileURL(resolvedPath).href);
  } catch (err) {
    console.error(`agent-booster import failed: ${err.message}`);
    console.error(`cwd was: ${process.cwd()}`);
    console.error('Run from a directory where the package resolves, e.g.:');
    console.error('  ( cd v3 && node ../plugins/ruflo-cost-tracker/scripts/bench.mjs )');
    process.exit(2);
  }
  const { AgentBooster } = AgentBoosterMod;
  const booster = new AgentBooster();

  const results = [];
  for (const c of corpus.cases) {
    const expectedTier1 = c.expectedTier1 !== false; // default true (corpus v1 compat)
    const t0 = Date.now();
    let out;
    try {
      out = await booster.apply({ code: c.code, edit: c.edit, language: c.language });
    } catch (e) {
      results.push({ id: c.id, intent: c.intent, expectedTier1, error: String(e.message).slice(0, 200), correct: false });
      continue;
    }
    const wallMs = Date.now() - t0;
    const correct = norm(out.output) === norm(c.expected);
    const lowConfidence = (out.confidence ?? 0) < 0.5;
    // For Tier 1 cases: "good" = correct.
    // For non-Tier 1 cases: "good" = booster correctly *escalates* (incorrect output OR low confidence).
    const escalatedCorrectly = !expectedTier1 && (!correct || lowConfidence);
    results.push({
      id: c.id,
      intent: c.intent,
      expectedTier1,
      success: !!out.success,
      correct,
      escalatedCorrectly,
      lowConfidence,
      latencyMs: out.latency ?? null,
      wallMs,
      confidence: out.confidence ?? null,
      strategy: out.strategy ?? null,
      tokensIn: out.tokens?.input ?? null,
      tokensOut: out.tokens?.output ?? null,
      ...(correct ? {} : { actualPrefix: norm(out.output).slice(0, 120), expectedPrefix: norm(c.expected).slice(0, 120) }),
    });
  }

  const tier1Cases = results.filter((r) => r.expectedTier1);
  const advCases = results.filter((r) => !r.expectedTier1);
  const tier1Passed = tier1Cases.filter((r) => r.correct).length;
  const tier1Total = tier1Cases.length;
  const advEscalated = advCases.filter((r) => r.escalatedCorrectly).length;
  const advTotal = advCases.length;

  const passed = results.filter((r) => r.correct).length;
  const total = results.length;
  const winRate = tier1Total ? tier1Passed / tier1Total : (total ? passed / total : 0);
  const escalationRate = advTotal ? advEscalated / advTotal : null;
  const successCount = results.filter((r) => r.success).length;

  const latencies = results.map((r) => r.latencyMs).filter((x) => typeof x === 'number');
  const wallTimes = results.map((r) => r.wallMs).filter((x) => typeof x === 'number');
  const confidences = results.map((r) => r.confidence).filter((x) => typeof x === 'number');

  const avg = (arr) => (arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0);

  // Optional: run the same corpus through one or more LLMs and record the comparison.
  let llmSummary = null;
  let llmResults = null;
  if (process.env.BENCH_LLM_BASELINE === '1') {
    ({ llmSummary, llmResults } = await runLlmBaseline(corpus.cases));
  }

  let anthropicSummaries = null; // Map<model, summary>
  let anthropicResults = null;   // Map<model, per-case-results>
  if (process.env.BENCH_ANTHROPIC === '1') {
    ({ anthropicSummaries, anthropicResults } = await runAnthropicBaseline(corpus.cases));
  }

  const summary = {
    runAt: new Date().toISOString(),
    corpusVersion: corpus.version,
    corpusSize: total,
    tier1Cases: tier1Total,
    adversarialCases: advTotal,
    winRate, // win rate over Tier 1 cases (the gate metric)
    winRatePct: pct(winRate),
    overallCorrect: total ? passed / total : 0, // diagnostic only
    escalationRate, // null if no adversarial cases; otherwise (correctly-escalated / adversarial)
    escalationRatePct: escalationRate == null ? 'n/a' : pct(escalationRate),
    successCount,
    avgLatencyMs: avg(latencies),
    p50LatencyMs: pcent(latencies, 50),
    p99LatencyMs: pcent(latencies, 99),
    maxLatencyMs: latencies.length ? Math.max(...latencies) : 0,
    avgWallMs: avg(wallTimes),
    avgConfidence: avg(confidences),
    minConfidence: confidences.length ? Math.min(...confidences) : 0,
    confidenceThreshold: 0.5,
    aboveThresholdCount: confidences.filter((c) => c >= 0.5).length,
    structuralCostUsd: 0, // no LLM call → no billing
    llmBaseline: llmSummary || (process.env.BENCH_LLM_BASELINE === '1' ? 'enabled-but-failed' : 'skipped'),
  };
  if (llmSummary) {
    // Direct apples-to-apples speedup ratio (booster vs LLM)
    summary.speedupVsLlm = llmSummary.avgLatencyMs / Math.max(summary.avgLatencyMs, 0.001);
    summary.costDeltaUsdPerEdit = llmSummary.avgCostUsdPerEdit; // booster side is $0
  }
  if (anthropicSummaries) {
    summary.anthropic = {};
    for (const [model, s] of Object.entries(anthropicSummaries)) {
      summary.anthropic[model] = {
        ...s,
        speedupVsBooster: s.avgLatencyMs / Math.max(summary.avgLatencyMs, 0.001),
        costSavedPerEditUsd: s.avgCostUsdPerEdit, // booster side is $0
      };
    }
  }

  const outDir = RUNS_DIR;
  mkdirSync(outDir, { recursive: true });
  const stamp = summary.runAt.replace(/[:.]/g, '-');
  const outPath = process.env.BENCH_OUT || join(outDir, `${stamp}.json`);
  const latestPath = join(outDir, 'latest.json');
  const payload = {
    summary,
    results,
    ...(llmResults ? { llmResults } : {}),
    ...(anthropicResults ? { anthropicResults } : {}),
  };
  writeFileSync(outPath, JSON.stringify(payload, null, 2));
  writeFileSync(latestPath, JSON.stringify(payload, null, 2));

  if (process.env.BENCH_QUIET !== '1') {
    console.log(`# Booster benchmark — ${summary.runAt}`);
    console.log('');
    console.log(`| Metric | Value |`);
    console.log(`|---|---:|`);
    console.log(`| Corpus size | ${total} (Tier 1: ${tier1Total}, adversarial: ${advTotal}) |`);
    console.log(`| **Win rate (Tier 1 cases)** | **${pct(winRate)}** (${tier1Passed}/${tier1Total}) |`);
    if (advTotal) {
      console.log(`| Escalation rate (adversarial) | ${pct(escalationRate)} (${advEscalated}/${advTotal}) |`);
    }
    console.log(`| Overall correct (diagnostic) | ${pct(total ? passed/total : 0)} (${passed}/${total}) |`);
    console.log(`| Success flag | ${successCount}/${total} |`);
    console.log(`| Avg latency | ${ms(summary.avgLatencyMs)} |`);
    console.log(`| p50 latency | ${ms(summary.p50LatencyMs)} |`);
    console.log(`| p99 latency | ${ms(summary.p99LatencyMs)} |`);
    console.log(`| Max latency | ${ms(summary.maxLatencyMs)} |`);
    console.log(`| Avg confidence | ${summary.avgConfidence.toFixed(3)} |`);
    console.log(`| Min confidence | ${summary.minConfidence.toFixed(3)} |`);
    console.log(`| Above 0.5 threshold | ${summary.aboveThresholdCount}/${confidences.length} |`);
    console.log(`| Structural cost | $${summary.structuralCostUsd} (no LLM call) |`);
    if (llmSummary) {
      console.log(`| LLM baseline model | ${llmSummary.model} |`);
      console.log(`| LLM avg latency | ${ms(llmSummary.avgLatencyMs)} |`);
      console.log(`| LLM win rate | ${pct(llmSummary.winRate)} (${llmSummary.passed}/${llmSummary.total}) |`);
      console.log(`| LLM avg cost/edit | $${llmSummary.avgCostUsdPerEdit.toFixed(6)} |`);
      console.log(`| **Measured speedup (booster vs LLM)** | **${summary.speedupVsLlm.toFixed(1)}×** |`);
      console.log(`| **Cost saved per edit** | **$${summary.costDeltaUsdPerEdit.toFixed(6)}** (100%) |`);
    } else {
      console.log(`| LLM baseline | ${summary.llmBaseline} |`);
    }
    console.log(``);
    if (anthropicSummaries) {
      console.log(`## Anthropic baseline\n`);
      console.log(`| Model | Avg latency | Win rate | Avg tokens (in/out) | Avg cost/edit | Speedup vs booster | Cost saved/edit |`);
      console.log(`|---|---:|---:|---:|---:|---:|---:|`);
      for (const [model, s] of Object.entries(anthropicSummaries)) {
        const speedup = (s.avgLatencyMs / Math.max(summary.avgLatencyMs, 0.001)).toFixed(1);
        console.log(`| \`${model}\` | ${ms(s.avgLatencyMs)} | ${pct(s.winRate)} (${s.passed}/${s.total}) | ${s.avgTokensIn.toFixed(0)} / ${s.avgTokensOut.toFixed(0)} | $${s.avgCostUsdPerEdit.toFixed(6)} | **${speedup}×** | **$${s.avgCostUsdPerEdit.toFixed(6)}** |`);
      }
      console.log(``);
    }
    const failed = results.filter((r) => !r.correct);
    if (failed.length) {
      console.log(`## Failures (${failed.length})`);
      for (const f of failed) {
        console.log(`- \`${f.id}\` (${f.intent}): ${f.error || `actual="${f.actualPrefix}" vs expected="${f.expectedPrefix}"`}`);
      }
    }
    console.log(``);
    console.log(`Saved: ${outPath}`);
    console.log(`Latest pointer: ${latestPath}`);
  }
}

// ─── LLM baseline ────────────────────────────────────────────────────────────

async function runLlmBaseline(cases) {
  const baseUrl = process.env.BENCH_LLM_BASE_URL || 'https://generativelanguage.googleapis.com/v1beta/openai/';
  const model = process.env.BENCH_LLM_MODEL || 'models/gemini-2.0-flash';
  const priceIn = parseFloat(process.env.BENCH_LLM_PRICE_IN || '0.10'); // $/1M input
  const priceOut = parseFloat(process.env.BENCH_LLM_PRICE_OUT || '0.40'); // $/1M output
  let apiKey = process.env.BENCH_LLM_API_KEY;
  if (!apiKey) {
    // Try to pull from gcloud (deployed ruvocal uses GOOGLE_AI_API_KEY)
    try {
      const { execSync } = await import('node:child_process');
      apiKey = execSync('gcloud secrets versions access latest --secret=GOOGLE_AI_API_KEY 2>/dev/null', { encoding: 'utf-8' }).trim();
    } catch { /* fall through */ }
  }
  if (!apiKey) {
    return { llmSummary: { error: 'no-api-key', baseUrl, model }, llmResults: [] };
  }

  const sys = `You apply code edits deterministically. Return ONLY the resulting code as a single fenced \`\`\`<lang> code block. No explanation, no commentary, no extra blocks. The output of the code block is the final source.`;
  const user = (c) => `Apply this edit. Return only the resulting code.\n\nLanguage: ${c.language}\n\nOriginal code:\n\`\`\`${c.language}\n${c.code}\n\`\`\`\n\nEdit instruction (target snippet):\n\`\`\`${c.language}\n${c.edit}\n\`\`\``;

  const fenceRe = /```(?:[a-zA-Z]+\n)?([\s\S]*?)```/;
  const out = [];
  let totIn = 0, totOut = 0, totLatencyMs = 0, passed = 0;
  for (const c of cases) {
    const t0 = Date.now();
    let body = null;
    try {
      const resp = await fetch(`${baseUrl.replace(/\/$/, '')}/chat/completions`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model,
          messages: [{ role: 'system', content: sys }, { role: 'user', content: user(c) }],
          max_tokens: 1024,
          temperature: 0,
        }),
      });
      body = await resp.json();
    } catch (e) {
      out.push({ id: c.id, intent: c.intent, error: String(e.message).slice(0, 200), correct: false, wallMs: Date.now() - t0 });
      continue;
    }
    const wallMs = Date.now() - t0;
    const content = body?.choices?.[0]?.message?.content ?? '';
    const m = fenceRe.exec(content);
    const extracted = (m ? m[1] : content).trim();
    const correct = norm(extracted) === norm(c.expected);
    if (correct) passed++;
    const inT = body?.usage?.prompt_tokens ?? 0;
    const outT = body?.usage?.completion_tokens ?? 0;
    totIn += inT; totOut += outT; totLatencyMs += wallMs;
    const cost = inT / 1e6 * priceIn + outT / 1e6 * priceOut;
    out.push({
      id: c.id, intent: c.intent, correct, wallMs,
      tokensIn: inT, tokensOut: outT, costUsd: cost,
      ...(correct ? {} : { actualPrefix: norm(extracted).slice(0, 120), expectedPrefix: norm(c.expected).slice(0, 120) }),
    });
  }
  const total = cases.length;
  const totalCost = out.reduce((s, r) => s + (r.costUsd || 0), 0);
  return {
    llmSummary: {
      model, baseUrl, total, passed,
      winRate: total ? passed / total : 0,
      avgLatencyMs: total ? totLatencyMs / total : 0,
      totalTokensIn: totIn,
      totalTokensOut: totOut,
      avgTokensIn: total ? totIn / total : 0,
      avgTokensOut: total ? totOut / total : 0,
      totalCostUsd: totalCost,
      avgCostUsdPerEdit: total ? totalCost / total : 0,
      pricing: { input_per_1M: priceIn, output_per_1M: priceOut },
    },
    llmResults: out,
  };
}

// ─── Anthropic baseline ──────────────────────────────────────────────────────

// Built-in pricing per 1M tokens (USD). Override with BENCH_ANTHROPIC_PRICING JSON env.
const ANTHROPIC_PRICING = {
  'claude-sonnet-4-6':  { input: 3.00,  output: 15.00 },
  'claude-opus-4-7':    { input: 15.00, output: 75.00 },
  'claude-haiku-4-5':   { input: 1.00,  output: 5.00 },
  'claude-haiku-4-5-20251001': { input: 1.00, output: 5.00 },
};

async function runAnthropicBaseline(cases) {
  let apiKey = process.env.BENCH_ANTHROPIC_API_KEY;
  if (!apiKey) {
    try {
      const { execSync } = await import('node:child_process');
      apiKey = execSync('gcloud secrets versions access latest --secret=ANTHROPIC_API_KEY 2>/dev/null', { encoding: 'utf-8' }).trim();
    } catch { /* fall through */ }
  }
  if (!apiKey) {
    return { anthropicSummaries: { _error: 'no-api-key' }, anthropicResults: {} };
  }

  let pricingOverride = {};
  if (process.env.BENCH_ANTHROPIC_PRICING) {
    try { pricingOverride = JSON.parse(process.env.BENCH_ANTHROPIC_PRICING); } catch { /* ignore */ }
  }
  const models = (process.env.BENCH_ANTHROPIC_MODELS || 'claude-sonnet-4-6,claude-opus-4-7')
    .split(',').map((s) => s.trim()).filter(Boolean);

  const sys = `You apply code edits deterministically. Return ONLY the resulting code as a single fenced \`\`\`<lang> code block. No explanation, no commentary, no extra blocks.`;
  const user = (c) => `Apply this edit. Return only the resulting code.\n\nLanguage: ${c.language}\n\nOriginal code:\n\`\`\`${c.language}\n${c.code}\n\`\`\`\n\nEdit instruction (target snippet):\n\`\`\`${c.language}\n${c.edit}\n\`\`\``;
  const fenceRe = /```(?:[a-zA-Z]+\n)?([\s\S]*?)```/;

  const summaries = {};
  const allResults = {};
  for (const model of models) {
    const pricing = pricingOverride[model] || ANTHROPIC_PRICING[model] || { input: 3, output: 15 };
    const out = [];
    let totIn = 0, totOut = 0, totLatencyMs = 0, passed = 0;
    for (const c of cases) {
      const t0 = Date.now();
      let body = null;
      try {
        const resp = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: {
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            model,
            max_tokens: 1024,
            system: sys,
            messages: [{ role: 'user', content: user(c) }],
          }),
        });
        body = await resp.json();
      } catch (e) {
        out.push({ id: c.id, intent: c.intent, error: String(e.message).slice(0, 200), correct: false, wallMs: Date.now() - t0 });
        continue;
      }
      const wallMs = Date.now() - t0;
      const text = body?.content?.[0]?.text ?? '';
      const m = fenceRe.exec(text);
      const extracted = (m ? m[1] : text).trim();
      const correct = norm(extracted) === norm(c.expected);
      if (correct) passed++;
      const inT = body?.usage?.input_tokens ?? 0;
      const outT = body?.usage?.output_tokens ?? 0;
      totIn += inT; totOut += outT; totLatencyMs += wallMs;
      const cost = inT / 1e6 * pricing.input + outT / 1e6 * pricing.output;
      out.push({
        id: c.id, intent: c.intent, correct, wallMs,
        tokensIn: inT, tokensOut: outT, costUsd: cost,
        ...(correct ? {} : { actualPrefix: norm(extracted).slice(0, 120), expectedPrefix: norm(c.expected).slice(0, 120) }),
      });
    }
    const total = cases.length;
    const totalCost = out.reduce((s, r) => s + (r.costUsd || 0), 0);
    summaries[model] = {
      model, total, passed,
      winRate: total ? passed / total : 0,
      avgLatencyMs: total ? totLatencyMs / total : 0,
      totalTokensIn: totIn,
      totalTokensOut: totOut,
      avgTokensIn: total ? totIn / total : 0,
      avgTokensOut: total ? totOut / total : 0,
      totalCostUsd: totalCost,
      avgCostUsdPerEdit: total ? totalCost / total : 0,
      pricing,
    };
    allResults[model] = out;
  }

  return { anthropicSummaries: summaries, anthropicResults: allResults };
}

main().catch((e) => {
  console.error('bench failed:', e);
  process.exit(1);
});

#!/usr/bin/env node
// cost-budget — set / get / check the project's cost budget against accumulated
// session spend in the `cost-tracking` namespace.
//
// Usage:
//   node scripts/budget.mjs set <usd>            # persist budget config
//   node scripts/budget.mjs get                  # show current budget config
//   node scripts/budget.mjs check                # compute utilization + alert level
//
// Env:
//   BUDGET_NAMESPACE=<name>   override (default: cost-tracking)
//   BUDGET_PERIOD=today|week|month|all   filter session totals by capturedAt
//   BUDGET_QUIET=1            machine-readable JSON only

import { spawnNpxSync } from './_npx.mjs';
// iter 73 — shared session-loader (was duplicated across 6 scripts).
// Only the session-list path consolidates; budget-config reads stay local
// because they have their own "latest stamp" upsert resolution logic.
import { loadSessions } from './_sessions.mjs';

// ADR-100 / #1748 Issue 3 — opt into cli-core's lite path with CLI_CORE=1.
// Cold-cache wall-time drops from ~25s to ~2s. JSON backend instead of
// SQLite/HNSW; semantic search degrades to substring (fine here — budget
// only does list/store/retrieve, no search). See cli-core/MIGRATION.md.
const CLI_PKG = process.env.CLI_CORE === '1'
  ? '@claude-flow/cli-core@alpha'
  : '@claude-flow/cli@latest';

const NS = process.env.BUDGET_NAMESPACE || 'cost-tracking';
const KEY = 'budget-config';

function memoryStore(key, value) {
  // The @claude-flow/cli memory layer has a UNIQUE-constraint quirk where
  // `store` rejects keys that `retrieve` doesn't surface. Workaround:
  // - For the budget-config key (single record), append a timestamp suffix
  //   on each write and update a small index that points at the latest.
  //   This avoids the conflict entirely. Retrieve resolves via the index.
  if (key === KEY) {
    const stamped = `${KEY}-${Date.now()}`;
    const r = spawnNpxSync([
      CLI_PKG, 'memory', 'store',
      '--namespace', NS, '--key', stamped, '--value', JSON.stringify(value),
    ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
    if (r.status !== 0) throw new Error(`memory store failed: ${r.stderr?.slice(0, 200) || r.status}`);
    // The "current pointer" is found at retrieval time by listing all
    // budget-config-* keys and picking the lexicographically-largest
    // (timestamp suffixes sort correctly because they are equal-width).
    return;
  }
  const r = spawnNpxSync([
    CLI_PKG, 'memory', 'store',
    '--namespace', NS, '--key', key, '--value', JSON.stringify(value),
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) throw new Error(`memory store failed: ${r.stderr?.slice(0, 200) || r.status}`);
}

function memoryRetrieveOne(key) {
  const r = spawnNpxSync([
    CLI_PKG, 'memory', 'retrieve',
    '--namespace', NS, '--key', key, '--value-only',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) return null;
  try { return JSON.parse((r.stdout || '').trim()); } catch { return null; }
}

function memoryRetrieve(key) {
  // For budget-config: pick the latest budget-config-<timestamp> entry.
  if (key === KEY) {
    const list = spawnNpxSync([
      CLI_PKG, 'memory', 'list',
      '--namespace', NS, '--format', 'json',
    ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
    if (list.status !== 0) return null;
    const m = /\[[\s\S]*\]/.exec(list.stdout || '');
    if (!m) return null;
    let entries;
    try { entries = JSON.parse(m[0]); } catch { return null; }
    const stamped = entries
      .map((e) => e.key)
      .filter((k) => typeof k === 'string' && /^budget-config-\d+$/.test(k))
      .sort();
    const latest = stamped[stamped.length - 1];
    if (!latest) {
      // fall back to plain budget-config (legacy / pre-stamping)
      return memoryRetrieveOne(KEY);
    }
    return memoryRetrieveOne(latest);
  }
  return memoryRetrieveOne(key);
}

function periodFilter(period) {
  const now = Date.now();
  const day = 24 * 3600 * 1000;
  if (period === 'today') return (ts) => ts && new Date(ts).toDateString() === new Date().toDateString();
  if (period === 'week')  return (ts) => ts && (now - new Date(ts).getTime()) < 7 * day;
  if (period === 'month') return (ts) => ts && (now - new Date(ts).getTime()) < 30 * day;
  return () => true; // 'all'
}

function alertLevel(utilization) {
  if (utilization >= 1.00) return { level: 'HARD_STOP', emoji: '🛑', threshold: 100 };
  if (utilization >= 0.90) return { level: 'CRITICAL',  emoji: '🔴', threshold: 90 };
  if (utilization >= 0.75) return { level: 'WARNING',   emoji: '🟠', threshold: 75 };
  if (utilization >= 0.50) return { level: 'INFO',      emoji: '🟡', threshold: 50 };
  return { level: 'OK', emoji: '🟢', threshold: 0 };
}

function recommendedAction(level) {
  return ({
    OK:        'within budget — no action.',
    INFO:      '50% consumed — log notification, no UX disruption.',
    WARNING:   '75% consumed — display warning, suggest optimizations (run /cost-optimize).',
    CRITICAL:  '90% consumed — urgent alert, recommend model downgrades, run /cost-optimize.',
    HARD_STOP: '100% consumed — halt non-essential agent spawns; review /cost-report and /cost-optimize before continuing.',
  }[level]);
}

function cmdSet(args) {
  const amount = parseFloat(args[0]);
  if (!Number.isFinite(amount) || amount <= 0) {
    console.error('usage: budget.mjs set <usd-amount>  (positive number)');
    process.exit(2);
  }
  const config = {
    budget_usd: amount,
    setAt: new Date().toISOString(),
    thresholds: { info: 0.50, warning: 0.75, critical: 0.90, hard_stop: 1.00 },
  };
  memoryStore(KEY, config);
  if (process.env.BUDGET_QUIET === '1') {
    console.log(JSON.stringify(config));
  } else {
    console.log(`✓ Budget set: $${amount.toFixed(2)} (namespace: ${NS}, key: ${KEY})`);
    console.log('  Alerts: 50% INFO · 75% WARNING · 90% CRITICAL · 100% HARD_STOP');
  }
}

function cmdGet() {
  const cfg = memoryRetrieve(KEY);
  if (process.env.BUDGET_QUIET === '1') {
    console.log(JSON.stringify(cfg || { error: 'no budget configured' }));
    return;
  }
  if (!cfg) {
    console.log(`No budget configured (namespace: ${NS}, key: ${KEY}).`);
    console.log('Set one with: cost budget set <usd>');
    process.exit(0);
  }
  console.log(`Budget: $${cfg.budget_usd?.toFixed(2)}  (set ${cfg.setAt})`);
  console.log(`Thresholds: 50/75/90/100%`);
}

function cmdCheck() {
  const cfg = memoryRetrieve(KEY);
  const period = process.env.BUDGET_PERIOD || 'all';
  const records = loadSessions(NS);
  const filt = periodFilter(period);
  const filtered = records.filter((r) => filt(r.capturedAt || r.endedAt));
  const totalSpend = filtered.reduce((s, r) => s + (r.total_cost_usd || 0), 0);
  if (!cfg || !Number.isFinite(cfg.budget_usd)) {
    const out = { period, totalSpend, recordCount: filtered.length, error: 'no budget configured' };
    // audit-allow: exit-bypass — no-budget path can't reach the HARD_STOP exit (no `alert` is computed in this branch).
    if (process.env.BUDGET_QUIET === '1') return console.log(JSON.stringify(out));
    console.log(`Period: ${period}`);
    console.log(`Spent so far: $${totalSpend.toFixed(2)} across ${filtered.length} sessions`);
    console.log(`No budget set — run \`cost budget set <usd>\` to enable alerts.`);
    return;
  }
  const utilization = totalSpend / cfg.budget_usd;
  const alert = alertLevel(utilization);
  const out = {
    period,
    budget_usd: cfg.budget_usd,
    spent_usd: totalSpend,
    remaining_usd: Math.max(0, cfg.budget_usd - totalSpend),
    utilization_pct: utilization * 100,
    level: alert.level,
    threshold: alert.threshold,
    recommended_action: recommendedAction(alert.level),
    sessionCount: filtered.length,
  };
  if (process.env.BUDGET_QUIET === '1') {
    console.log(JSON.stringify(out));
  } else {
    console.log(`# Budget check (period: ${period})`);
    console.log('');
    console.log(`| Metric | Value |`);
    console.log(`|---|---:|`);
    console.log(`| Budget | $${cfg.budget_usd.toFixed(2)} |`);
    console.log(`| Spent | $${totalSpend.toFixed(2)} |`);
    console.log(`| Remaining | $${out.remaining_usd.toFixed(2)} |`);
    console.log(`| Utilization | ${out.utilization_pct.toFixed(1)}% |`);
    console.log(`| Sessions counted | ${filtered.length} |`);
    console.log(`| **Alert** | **${alert.emoji} ${alert.level}** |`);
    console.log('');
    console.log(`Action: ${out.recommended_action}`);
  }
  // CRITICAL: must run in BOTH branches — otherwise BUDGET_QUIET=1 silently
  // swallowed HARD_STOP, breaking cost-health composite gate (iter 75 fix).
  if (alert.level === 'HARD_STOP') process.exit(1);
}

function main() {
  const [cmd, ...rest] = process.argv.slice(2);
  switch (cmd) {
    case 'set':   return cmdSet(rest);
    case 'get':   return cmdGet();
    case 'check': return cmdCheck();
    default:
      console.error('usage: budget.mjs {set <usd>|get|check}');
      process.exit(2);
  }
}

main();

#!/usr/bin/env node
// cost-burn — burn-rate trend over time + acceleration alert.
//
// Iters 34 + 50 of ADR-149 router work added windowed-trend visibility
// and drift-alert exit codes. This is the cost-tracker plugin equivalent
// for session spend: bin sessions into daily (or custom-duration) buckets,
// surface trend, and optionally fail builds on rate acceleration.
//
// METHOD
//   1. Read `cost-tracking` namespace session records.
//   2. Bin into buckets of `--bucket` duration (default 1d) over `--lookback`
//      window (default 14d). Each bucket gets {n, spend, avgPerSession}.
//   3. Compute window-over-window delta: latest bucket's spend vs the mean
//      of the prior N buckets (default: all prior buckets).
//   4. If `--alert-on-acceleration-pct N` is set AND the latest bucket
//      spend is > (prior mean × (1 + N/100)), exit 1 with an alert message.
//
// Distinct from `cost-trend` (which surfaces BENCHMARK drift across
// docs/benchmarks/runs/*.json). This tracks PRODUCTION spend over time.
//
// Pairs with:
//   - cost-budget-check    (reactive: "have we crossed?")
//   - cost-projection      (predictive: "when will we cross?")
//   - cost-counterfactual  (comparative: "is routing earning its keep?")
//   - cost-burn            (trend: "is daily burn accelerating?")  ← this
//
// USAGE
//   node scripts/burn.mjs                                           # default 14d / 1d bins
//   node scripts/burn.mjs --bucket 1d --lookback 30d                # daily bins, last month
//   node scripts/burn.mjs --bucket 1w --lookback 90d                # weekly bins, last quarter
//   node scripts/burn.mjs --alert-on-acceleration-pct 50            # exit 1 if latest > +50% vs prior mean
//   node scripts/burn.mjs --format json
//
// Env: BURN_NAMESPACE (default cost-tracking), BURN_QUIET=1.

// iter 73 — shared session-loader (was duplicated across 6 scripts).
import { loadSessions, sessionTs, parseDurationMs } from './_sessions.mjs';

const NS = process.env.BURN_NAMESPACE || 'cost-tracking';

const ARGS = (() => {
  const a = { bucket: '1d', lookback: '14d', alertPct: null, format: 'table' };
  if (process.env.BURN_QUIET === '1') a.format = 'json';
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--bucket') a.bucket = process.argv[++i];
    else if (v === '--lookback') a.lookback = process.argv[++i];
    else if (v === '--alert-on-acceleration-pct') a.alertPct = parseFloat(process.argv[++i]);
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function main() {
  const bucketMs = parseDurationMs(ARGS.bucket);
  const lookbackMs = parseDurationMs(ARGS.lookback);
  if (!bucketMs) {
    console.error(`burn: --bucket must be N(h|d|w|m); got "${ARGS.bucket}"`);
    process.exit(2);
  }
  if (!lookbackMs) {
    console.error(`burn: --lookback must be N(h|d|w|m); got "${ARGS.lookback}"`);
    process.exit(2);
  }
  if (bucketMs > lookbackMs) {
    console.error(`burn: --bucket (${ARGS.bucket}) cannot exceed --lookback (${ARGS.lookback})`);
    process.exit(2);
  }

  const now = Date.now();
  const cutoffMs = now - lookbackMs;

  // Read + filter sessions (shared loader, iter 73).
  const records = loadSessions(NS);
  const windowed = records.filter((r) => sessionTs(r) >= cutoffMs);

  // Bin: bucket index counts BACKWARDS from now, so the LAST bucket is
  // "the most recent <bucket>". Operators read newest-first.
  // bucket index 0 = newest (now-bucketMs .. now), index 1 = (now-2*bucketMs .. now-bucketMs), etc.
  const numBuckets = Math.ceil(lookbackMs / bucketMs);
  const buckets = Array.from({ length: numBuckets }, (_, i) => ({
    index: i,
    startMs: now - (i + 1) * bucketMs,
    endMs: now - i * bucketMs,
    n: 0,
    spendUsd: 0,
  }));
  for (const rec of windowed) {
    const ts = sessionTs(rec);
    const offsetMs = now - ts;
    const idx = Math.floor(offsetMs / bucketMs);
    if (idx >= 0 && idx < numBuckets) {
      buckets[idx].n++;
      buckets[idx].spendUsd += rec.total_cost_usd || 0;
    }
  }

  // Window-over-window: latest bucket (index 0) vs mean of prior buckets
  // that have at least one session (avoid divide-by-zero on sparse history).
  const latest = buckets[0];
  const priorNonEmpty = buckets.slice(1).filter((b) => b.n > 0);
  const priorMean = priorNonEmpty.length > 0
    ? priorNonEmpty.reduce((s, b) => s + b.spendUsd, 0) / priorNonEmpty.length
    : 0;
  const deltaUsd = latest.spendUsd - priorMean;
  const deltaPct = priorMean > 0 ? (deltaUsd / priorMean) * 100 : (latest.spendUsd > 0 ? Infinity : 0);

  // Alert check.
  let alertTriggered = false;
  let alertReason = null;
  if (ARGS.alertPct !== null) {
    if (!isFinite(ARGS.alertPct) || ARGS.alertPct <= 0) {
      console.error(`burn: --alert-on-acceleration-pct must be > 0; got ${ARGS.alertPct}`);
      process.exit(2);
    }
    if (priorNonEmpty.length === 0) {
      alertReason = `skipped (no prior non-empty buckets to compare — need ≥1)`;
    } else if (priorMean === 0) {
      alertReason = `skipped (prior buckets are all $0)`;
    } else if (deltaPct > ARGS.alertPct) {
      alertTriggered = true;
      alertReason = `latest bucket $${latest.spendUsd.toFixed(6)} is ${deltaPct.toFixed(1)}% above prior mean $${priorMean.toFixed(6)} (threshold +${ARGS.alertPct}%)`;
    } else {
      alertReason = `latest bucket within +${ARGS.alertPct}% of prior mean (actual delta: ${deltaPct.toFixed(1)}%) — OK`;
    }
  }

  const payload = {
    namespace: NS,
    config: { bucket: ARGS.bucket, lookback: ARGS.lookback, alertOnAccelerationPct: ARGS.alertPct },
    bucketsConsidered: buckets.length,
    sessionsInLookback: windowed.length,
    latest: {
      windowStart: new Date(latest.startMs).toISOString(),
      windowEnd: new Date(latest.endMs).toISOString(),
      sessions: latest.n,
      spendUsd: Math.round(latest.spendUsd * 1e6) / 1e6,
    },
    priorMean: {
      bucketsConsidered: priorNonEmpty.length,
      meanSpendUsd: Math.round(priorMean * 1e6) / 1e6,
    },
    delta: {
      deltaUsd: Math.round(deltaUsd * 1e6) / 1e6,
      deltaPct: isFinite(deltaPct) ? Math.round(deltaPct * 100) / 100 : null,
    },
    series: buckets.map((b) => ({
      bucketIndex: b.index,
      windowStart: new Date(b.startMs).toISOString(),
      windowEnd: new Date(b.endMs).toISOString(),
      sessions: b.n,
      spendUsd: Math.round(b.spendUsd * 1e6) / 1e6,
    })),
    alert: ARGS.alertPct !== null ? {
      triggered: alertTriggered,
      reason: alertReason,
      thresholdPct: ARGS.alertPct,
    } : null,
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# cost-burn (bucket=${ARGS.bucket}, lookback=${ARGS.lookback})`);
    console.log('');
    console.log(`| Metric | Value |`);
    console.log(`|---|---:|`);
    console.log(`| Buckets considered | ${buckets.length} |`);
    console.log(`| Sessions in lookback | ${windowed.length} |`);
    console.log(`| Latest bucket spend | $${latest.spendUsd.toFixed(6)} (${latest.n} sessions) |`);
    console.log(`| Prior bucket mean | $${priorMean.toFixed(6)} (${priorNonEmpty.length} non-empty buckets) |`);
    const deltaStr = deltaUsd >= 0 ? `+$${deltaUsd.toFixed(6)}` : `-$${Math.abs(deltaUsd).toFixed(6)}`;
    const pctStr = isFinite(deltaPct) ? `${deltaPct.toFixed(2)}%` : (priorMean === 0 ? 'new' : '∞');
    console.log(`| **Delta (latest vs prior mean)** | **${deltaStr} (${pctStr})** |`);
    console.log('');
    console.log('## Bucket series (newest first)');
    console.log('');
    console.log('| # | Window | Sessions | Spend |');
    console.log('|---:|---|---:|---:|');
    for (const b of buckets) {
      const startShort = new Date(b.startMs).toISOString().slice(0, 16).replace('T', ' ');
      const endShort = new Date(b.endMs).toISOString().slice(0, 16).replace('T', ' ');
      console.log(`| ${b.index} | ${startShort} → ${endShort} | ${b.n} | $${b.spendUsd.toFixed(6)} |`);
    }
    console.log('');
    if (alertReason !== null) {
      if (alertTriggered) {
        console.log(`⚠ **ALERT**: ${alertReason}`);
      } else {
        console.log(`✓ ${alertReason}`);
      }
      console.log('');
    }
  }

  if (alertTriggered) process.exit(1);
}

main();

#!/usr/bin/env node
// cost-compact — wraps getTokenOptimizer().getCompactContext() so the
// cost-compact-context skill can invoke a single command instead of an
// inlined Node one-liner.
//
// Resolution strategy (#1930): pnpm-workspace marketplace installs don't
// hoist `@claude-flow/integration` into `v3/node_modules/`, so resolving
// from cwd alone breaks. Try, in order:
//   1. createRequire(cwd)           — works for npm-style hoisted installs
//   2. createRequire(script-dir)    — works when run from inside the plugin
//   3. absolute path from this file — works on the marketplace layout
//      (script lives at <ruflo>/plugins/ruflo-cost-tracker/scripts/, the
//       integration package at <ruflo>/v3/@claude-flow/integration/)
//
// Also: agentic-flow's index.js binds `process.env.HEALTH_PORT || 8080`
// unconditionally on import. On any host with something already on 8080
// (k8s NodePort, forwarded dev server) the import EADDRINUSEs. Set
// HEALTH_PORT to 0 by default so the OS picks a free port — users can
// still override with an explicit value.
//
// Usage:
//   node scripts/compact.mjs "<query>"
//
// Optional env:
//   COMPACT_QUIET=1   emit JSON only (no markdown banner)
//   HEALTH_PORT=<n>   override agentic-flow's health-server port (default 0)

import { createRequire } from 'node:module';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { join, resolve, dirname, isAbsolute } from 'node:path';
import { existsSync } from 'node:fs';

// #1930 step 4: pick a free port unless caller pinned one. Set BEFORE the
// dynamic import below — agentic-flow reads HEALTH_PORT at module-load time.
if (!process.env.HEALTH_PORT) process.env.HEALTH_PORT = '0';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

function tryResolveFrom(anchorPath) {
  try {
    const req = createRequire(anchorPath);
    return req.resolve('@claude-flow/integration/token-optimizer');
  } catch {
    return null;
  }
}

function tryAbsolutePath() {
  // Walk up from this script looking for `v3/@claude-flow/integration/dist/token-optimizer.js`.
  // Handles the marketplace layout (script at plugins/ruflo-cost-tracker/scripts/) and the
  // dev-repo layout. Caps depth at 6 to avoid runaway traversal.
  let dir = __dirname;
  for (let i = 0; i < 6; i++) {
    const candidate = join(dir, 'v3', '@claude-flow', 'integration', 'dist', 'token-optimizer.js');
    if (existsSync(candidate)) return candidate;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

async function main() {
  const query = process.argv[2] || '';
  if (!query) {
    console.error('usage: compact.mjs "<query>"');
    process.exit(2);
  }

  // Resolution chain — cwd → script dir → absolute fallback (#1930 step 5)
  const candidates = [
    tryResolveFrom(join(process.cwd(), 'package.json')),
    tryResolveFrom(join(__dirname, 'package.json')),
    tryAbsolutePath(),
  ].filter(Boolean);

  let mod;
  let lastErr = null;
  for (const resolved of candidates) {
    try {
      // Skip dangling resolutions that point at a non-existent file (a
      // common pnpm-workspace symptom when dist/ wasn't built — see
      // #1930 step 1).
      const abs = isAbsolute(resolved) ? resolved : resolve(resolved);
      if (!existsSync(abs)) {
        lastErr = new Error(`token-optimizer.js missing at ${abs} — run \`cd v3/@claude-flow/integration && pnpm run build\` (#1930 step 1)`);
        continue;
      }
      mod = await import(pathToFileURL(abs).href);
      break;
    } catch (err) {
      lastErr = err;
    }
  }

  if (!mod) {
    const reason = lastErr
      ? String(lastErr.message || lastErr).slice(0, 300)
      : 'Cannot find module @claude-flow/integration/token-optimizer';
    const out = {
      bridgeUnavailable: true,
      reason,
      memoriesRetrieved: 0,
      tokensSaved: 0,
      agenticFlowAvailable: false,
      hint: 'Tried cwd, script dir, and absolute path from this script — see #1930 for full troubleshooting.',
    };
    if (process.env.COMPACT_QUIET === '1') return console.log(JSON.stringify(out));
    console.log(`# cost-compact-context\n\nbridge unavailable: ${reason}`);
    console.log('');
    console.log('Tried:');
    console.log('  - resolve from cwd');
    console.log('  - resolve from script dir');
    console.log('  - absolute path walk from this script (looking for v3/@claude-flow/integration/dist/token-optimizer.js)');
    console.log('');
    console.log('If `@claude-flow/integration` is installed but `dist/` is missing, run:');
    console.log('  cd v3/@claude-flow/integration && pnpm run build');
    return;
  }

  const { getTokenOptimizer } = mod;
  const opt = await getTokenOptimizer();
  const ctx = await opt.getCompactContext(query);
  const stats = opt.getStats();

  const out = {
    query,
    memoriesRetrieved: ctx.memories?.length ?? 0,
    tokensSaved: ctx.tokensSaved ?? 0,
    agenticFlowAvailable: !!stats?.agenticFlowAvailable,
    cacheHitRate: stats?.cacheHitRate || '0%',
    upstreamReported: 'tokensSaved is bridge-reported (heuristic), not measured against a no-RAG baseline',
  };

  if (process.env.COMPACT_QUIET === '1') return console.log(JSON.stringify(out));
  console.log(`# cost-compact-context — query: "${query}"`);
  console.log('');
  console.log('| Metric | Value |');
  console.log('|---|---:|');
  console.log(`| Memories retrieved | ${out.memoriesRetrieved} |`);
  console.log(`| Tokens saved (bridge-reported) | ${out.tokensSaved} |`);
  console.log(`| agentic-flow bridge available | ${out.agenticFlowAvailable} |`);
  console.log(`| Cache hit rate | ${out.cacheHitRate} |`);
  console.log('');
  console.log(`> ${out.upstreamReported}`);
  if (!out.agenticFlowAvailable) {
    console.log('');
    console.log('agentic-flow not installed — bridge returns inert results. No compact-context savings.');
  }
}

main().catch((e) => { console.error('compact.mjs failed:', e.message || e); process.exit(1); });

#!/usr/bin/env node
// cost-conversation — list all session records in the cost-tracking namespace
// and show cost-per-conversation. Until now reports were per-agent / per-model;
// this gives a per-conversation timeline.
//
// Usage:
//   node scripts/conversation.mjs                    # markdown table
//   CONV_FORMAT=json node scripts/conversation.mjs   # JSON
//   CONV_LIMIT=20 node scripts/conversation.mjs      # most recent N
//   CONV_NAMESPACE=cost-tracking (default)

// iter 73 — shared session-loader (was duplicated across 6 scripts).
// ADR-100 / #1748 Issue 3 — CLI_CORE=1 routes to lite cli-core (~2s cold-cache).
import { loadSessions, memoryListSessionKeys } from './_sessions.mjs';

const NS = process.env.CONV_NAMESPACE || 'cost-tracking';

function fmtUsd(n) { return `$${(n || 0).toFixed(4)}`; }
function fmtTs(s) { return s ? new Date(s).toISOString().replace('T', ' ').replace(/\.\d+Z/, '') : ''; }
function topModel(byModel) {
  const entries = Object.entries(byModel || {}).sort((a, b) => (b[1].cost_usd || 0) - (a[1].cost_usd || 0));
  return entries[0]?.[0] || '—';
}

function main() {
  const keys = memoryListSessionKeys(NS);
  if (!keys.length) {
    console.log(`No sessions in '${NS}'. Run \`cost track\` first.`);
    return;
  }
  const records = loadSessions(NS);
  records.sort((a, b) => (a.startedAt || '').localeCompare(b.startedAt || ''));

  const limit = parseInt(process.env.CONV_LIMIT || '50', 10);
  const recent = records.slice(-limit);

  const total = records.reduce((s, r) => s + (r.total_cost_usd || 0), 0);
  const byTier = { haiku: 0, sonnet: 0, opus: 0, unknown: 0 };
  for (const r of records) {
    if (r.byTier) {
      for (const [t, v] of Object.entries(r.byTier)) byTier[t] = (byTier[t] || 0) + v;
    }
  }

  if (process.env.CONV_FORMAT === 'json') {
    console.log(JSON.stringify({
      conversationCount: records.length,
      shownCount: recent.length,
      total_cost_usd: total,
      byTier,
      conversations: recent,
    }, null, 2));
    return;
  }

  console.log(`# cost-per-conversation — ${records.length} conversations in '${NS}'`);
  console.log('');
  console.log(`| Metric | Value |`);
  console.log(`|---|---:|`);
  console.log(`| Conversations tracked | ${records.length} |`);
  console.log(`| **Total cost (all)** | **${fmtUsd(total)}** |`);
  for (const t of ['haiku', 'sonnet', 'opus', 'unknown']) {
    if (byTier[t] > 0) console.log(`| Tier ${t} | ${fmtUsd(byTier[t])} |`);
  }
  console.log('');
  console.log(`## ${recent.length === records.length ? 'All' : 'Most recent ' + recent.length} conversations`);
  console.log('');
  console.log('| Started | Session | Messages | Top model | Cost |');
  console.log('|---|---|---:|---|---:|');
  for (const r of recent) {
    const sid = (r.sessionId || '').slice(0, 8);
    console.log(`| ${fmtTs(r.startedAt)} | \`${sid}\` | ${r.messageCount || 0} | \`${topModel(r.byModel)}\` | ${fmtUsd(r.total_cost_usd)} |`);
  }
}

main();

#!/usr/bin/env node
// cost-counterfactual — actual vs hypothetical baseline cost analysis.
//
// Iters 32-33 of ADR-149 router work added multi-baseline counterfactual
// analysis for routing decisions. This is the cost-tracker equivalent for
// session-level spend: what would each session have cost if every message
// had been routed to a fixed tier (always-haiku / always-sonnet / always-opus)?
//
// METHOD
//   1. Read `cost-tracking` namespace session records (same source as
//      budget.mjs / conversation.mjs).
//   2. For each session: sum token totals across all `byModel[*]` entries.
//   3. For each baseline tier (default: all three):
//        counterfactualCost = (input_tokens / 1M × tier.input)
//                           + (output_tokens / 1M × tier.output)
//                           + (cache_creation / 1M × tier.cache_write)
//                           + (cache_read     / 1M × tier.cache_read)
//   4. Compute savings: counterfactual − actual = how much routing saved
//      (positive) or lost (negative) vs the baseline.
//   5. Aggregate across sessions; emit per-baseline totals + savings %.
//
// Pairs with `cost-budget-check` and `cost-projection`:
//   - check:        "have we crossed a threshold?" (reactive)
//   - projection:   "when will we cross a threshold?" (predictive)
//   - counterfactual: "is the routing earning its keep?" (comparative)
//
// USAGE
//   node scripts/counterfactual.mjs                                # all sessions
//   node scripts/counterfactual.mjs --since 7d                     # last week
//   node scripts/counterfactual.mjs --baseline always-haiku        # single baseline
//   node scripts/counterfactual.mjs --format json                  # pipe-friendly
//
// Env: COUNTERFACTUAL_NAMESPACE (default cost-tracking), COUNTERFACTUAL_QUIET=1.

// iter 68 — shared PRICING + cost helpers.
import { costAtTier } from './_prices.mjs';
// iter 73 — shared session-loader.
import { loadSessions, sessionTs, parseDurationMs } from './_sessions.mjs';

const NS = process.env.COUNTERFACTUAL_NAMESPACE || 'cost-tracking';

const ALL_BASELINES = ['always-haiku', 'always-sonnet', 'always-opus'];

const ARGS = (() => {
  const a = { since: null, baseline: 'all', format: 'table' };
  if (process.env.COUNTERFACTUAL_QUIET === '1') a.format = 'json';
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--since') a.since = process.argv[++i];
    else if (v === '--baseline') a.baseline = process.argv[++i];
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function tierFromBaseline(baseline) {
  switch (baseline) {
    case 'always-haiku':  return 'haiku';
    case 'always-sonnet': return 'sonnet';
    case 'always-opus':   return 'opus';
    default: return null;
  }
}

function sumSessionTokens(rec) {
  const totals = { input: 0, output: 0, cache_write: 0, cache_read: 0 };
  const byModel = rec.byModel || {};
  for (const slot of Object.values(byModel)) {
    totals.input       += slot.input_tokens || 0;
    totals.output      += slot.output_tokens || 0;
    totals.cache_write += slot.cache_creation_input_tokens || 0;
    totals.cache_read  += slot.cache_read_input_tokens || 0;
  }
  return totals;
}

function main() {
  // Validate baseline arg.
  const baselines = ARGS.baseline === 'all'
    ? ALL_BASELINES
    : [ARGS.baseline];
  for (const b of baselines) {
    if (!tierFromBaseline(b)) {
      console.error(`counterfactual: invalid --baseline "${b}" (must be one of: ${ALL_BASELINES.join(' | ')} | all)`);
      process.exit(2);
    }
  }

  // Read + filter sessions (shared loader, iter 73).
  const records = loadSessions(NS);

  let cutoffMs = null;
  if (ARGS.since) {
    const ms = parseDurationMs(ARGS.since);
    if (!ms) {
      console.error(`counterfactual: --since must be N(h|d|w|m); got "${ARGS.since}"`);
      process.exit(2);
    }
    cutoffMs = Date.now() - ms;
  }
  const filtered = cutoffMs === null
    ? records
    : records.filter((r) => sessionTs(r) >= cutoffMs);

  // Aggregate.
  let actualUsd = 0;
  const tokens = { input: 0, output: 0, cache_write: 0, cache_read: 0 };
  for (const rec of filtered) {
    actualUsd += rec.total_cost_usd || 0;
    const t = sumSessionTokens(rec);
    tokens.input += t.input;
    tokens.output += t.output;
    tokens.cache_write += t.cache_write;
    tokens.cache_read += t.cache_read;
  }

  const baselineResults = baselines.map((b) => {
    const tier = tierFromBaseline(b);
    const counterfactualUsd = costAtTier(tokens, tier);
    const savingsUsd = counterfactualUsd - actualUsd;
    const savingsPct = counterfactualUsd > 0
      ? (savingsUsd / counterfactualUsd) * 100
      : 0;
    return {
      baseline: b,
      tier,
      counterfactualUsd: Math.round(counterfactualUsd * 1e6) / 1e6,
      actualUsd: Math.round(actualUsd * 1e6) / 1e6,
      savingsUsd: Math.round(savingsUsd * 1e6) / 1e6,
      savingsPct: Math.round(savingsPct * 100) / 100,
    };
  });

  const payload = {
    namespace: NS,
    filters: { since: ARGS.since, baseline: ARGS.baseline },
    sessionsConsidered: filtered.length,
    tokensTotal: tokens,
    actualUsd: Math.round(actualUsd * 1e6) / 1e6,
    baselines: baselineResults,
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
    return;
  }

  // Markdown / human output.
  console.log(`# cost-counterfactual${ARGS.since ? ` (since ${ARGS.since})` : ' (all-time)'}`);
  console.log('');
  console.log(`| Metric | Value |`);
  console.log(`|---|---:|`);
  console.log(`| Sessions considered | ${filtered.length} |`);
  console.log(`| Total input tokens | ${tokens.input.toLocaleString()} |`);
  console.log(`| Total output tokens | ${tokens.output.toLocaleString()} |`);
  console.log(`| Total cache_write tokens | ${tokens.cache_write.toLocaleString()} |`);
  console.log(`| Total cache_read tokens | ${tokens.cache_read.toLocaleString()} |`);
  console.log(`| **Actual spend** | **$${actualUsd.toFixed(6)}** |`);
  console.log('');
  if (filtered.length === 0) {
    console.log('_No sessions in window — nothing to compare. Run `cost track` after agent work to populate `cost-tracking`._');
    console.log('');
    return;
  }
  console.log('## Counterfactual baselines (what would the same tokens have cost?)');
  console.log('');
  console.log('| Baseline | Hypothetical cost | Actual | Savings | % saved |');
  console.log('|---|---:|---:|---:|---:|');
  for (const r of baselineResults) {
    const savingsCell = r.savingsUsd >= 0
      ? `+$${r.savingsUsd.toFixed(6)}`
      : `-$${Math.abs(r.savingsUsd).toFixed(6)}`;
    const pctCell = r.savingsPct >= 0
      ? `${r.savingsPct.toFixed(2)}%`
      : `${r.savingsPct.toFixed(2)}%`;
    console.log(`| \`${r.baseline}\` | $${r.counterfactualUsd.toFixed(6)} | $${actualUsd.toFixed(6)} | ${savingsCell} | ${pctCell} |`);
  }
  console.log('');
  console.log('_Positive savings = routing chose cheaper models than the baseline._');
  console.log('_Negative savings = routing chose more-expensive models than the baseline (e.g. always-haiku was cheaper)._');
  if (baselines.length > 1) {
    console.log('_When always-haiku shows negative savings, qualityBar may be set too high; investigate via `cost optimize`._');
  }
  console.log('');
}

main();

#!/usr/bin/env node
// cost-diff — snapshot delta between two cost-summary JSON outputs.
//
// Consumes the stable JSON contract emitted by `cost summary --format json`.
// Use it to answer "what changed?" between two known-good states:
//   - "Did this PR add expensive sessions?" (baseline = main, current = PR)
//   - "Has spend shifted between tiers since the last release?"
//   - "Which models grew/shrank in usage week-over-week?"
//
// This is the COMPLEMENT to cost-counterfactual (hypothetical baselines)
// and cost-burn (latest-bucket vs prior mean). Where those answer
// "what could have been?" and "is the AVERAGE shifting?", cost-diff
// answers "what changed between these two specific snapshots?".
//
// USAGE
//   cost summary --format json > /tmp/baseline.json   # before
//   cost summary --format json > /tmp/current.json    # after
//   node scripts/diff.mjs --baseline /tmp/baseline.json --current /tmp/current.json
//   node scripts/diff.mjs ... --alert-on-pct 10       # exit 1 if total grew >10%
//   node scripts/diff.mjs ... --alert-on-usd 5.00     # exit 1 if total grew >$5
//   node scripts/diff.mjs ... --format json           # CI-consumable
//
// EXIT CODES
//   0  no alert (or no thresholds configured)
//   1  --alert-on-* threshold exceeded
//   2  config error (missing files, invalid JSON, etc.)

import { readFileSync, existsSync } from 'node:fs';

const ARGS = (() => {
  const a = {
    baseline: null, current: null,
    alertPct: null, alertUsd: null,
    // iter 86 — per-token-class % thresholds. Format: --alert-on-class-pct
    // cache_write:50 (or comma-separated: cache_write:50,output:25). Lets
    // CI catch regressions that grow ONE class disproportionately even if
    // the total USD delta is modest (the iter-82 bug class precedent).
    alertClassPct: {},  // { className: thresholdPct }
    format: 'table',
  };
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--baseline') a.baseline = process.argv[++i];
    else if (v === '--current') a.current = process.argv[++i];
    else if (v === '--alert-on-pct') a.alertPct = parseFloat(process.argv[++i]);
    else if (v === '--alert-on-usd') a.alertUsd = parseFloat(process.argv[++i]);
    else if (v === '--alert-on-class-pct') {
      const spec = process.argv[++i] || '';
      for (const pair of spec.split(',').map((s) => s.trim()).filter(Boolean)) {
        const m = /^(\w+):([\d.]+)$/.exec(pair);
        if (!m) {
          console.error(`cost-diff: --alert-on-class-pct expects "<class>:<pct>" pairs; got "${pair}"`);
          process.exit(2);
        }
        const cls = m[1], pct = parseFloat(m[2]);
        if (!['input', 'output', 'cache_write', 'cache_read'].includes(cls)) {
          console.error(`cost-diff: --alert-on-class-pct class must be one of input|output|cache_write|cache_read; got "${cls}"`);
          process.exit(2);
        }
        if (!isFinite(pct) || pct <= 0) {
          console.error(`cost-diff: --alert-on-class-pct threshold must be > 0; got ${pct}`);
          process.exit(2);
        }
        a.alertClassPct[cls] = pct;
      }
    }
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

function loadSnapshot(path, label) {
  if (!path) {
    console.error(`cost-diff: --${label} is required (a cost-summary JSON file)`);
    process.exit(2);
  }
  if (!existsSync(path)) {
    console.error(`cost-diff: ${label} file not found: ${path}`);
    process.exit(2);
  }
  let raw;
  try { raw = readFileSync(path, 'utf-8'); }
  catch (e) {
    console.error(`cost-diff: cannot read ${label}: ${e.message}`);
    process.exit(2);
  }
  let json;
  try { json = JSON.parse(raw); }
  catch (e) {
    console.error(`cost-diff: ${label} is not valid JSON: ${e.message}`);
    process.exit(2);
  }
  // Sanity check on shape — must look like a cost-summary output.
  if (typeof json.total_cost_usd !== 'number' || typeof json.sessionCount !== 'number') {
    console.error(`cost-diff: ${label} doesn't look like cost-summary output (missing total_cost_usd or sessionCount)`);
    process.exit(2);
  }
  return json;
}

function diffNumber(b, c) {
  const delta = c - b;
  const pct = b > 0 ? (delta / b) * 100 : (c > 0 ? Infinity : 0);
  return { baseline: b, current: c, delta, pct };
}

function diffMap(bMap, cMap) {
  // bMap/cMap: { key: number } or { key: { cost_usd } }
  const keys = new Set([...Object.keys(bMap || {}), ...Object.keys(cMap || {})]);
  const out = [];
  for (const k of keys) {
    const bv = typeof bMap[k] === 'object' ? (bMap[k]?.cost_usd ?? 0) : (bMap[k] ?? 0);
    const cv = typeof cMap[k] === 'object' ? (cMap[k]?.cost_usd ?? 0) : (cMap[k] ?? 0);
    if (bv === 0 && cv === 0) continue;
    out.push({ key: k, ...diffNumber(bv, cv), status: bv === 0 ? 'added' : (cv === 0 ? 'removed' : 'changed') });
  }
  out.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
  return out;
}

function main() {
  const baseline = loadSnapshot(ARGS.baseline, 'baseline');
  const current = loadSnapshot(ARGS.current, 'current');

  const total = diffNumber(baseline.total_cost_usd, current.total_cost_usd);
  const sessions = diffNumber(baseline.sessionCount, current.sessionCount);
  const tierDeltas = diffMap(baseline.byTier || {}, current.byTier || {});
  const modelDeltas = diffMap(baseline.byModel || {}, current.byModel || {});
  // iter 85 — surface per-token-class deltas. Without this a regression
  // that 10×'d cache_write tokens only showed up in USD totals; operators
  // couldn't see WHERE the growth came from. byTokenClass is emitted by
  // cost-summary (iter 84). Falls back gracefully if either snapshot
  // lacks the field (legacy snapshots).
  const tokenClassDeltas = (baseline.byTokenClass || current.byTokenClass)
    ? diffMap(baseline.byTokenClass || {}, current.byTokenClass || {})
    : null;

  // Alert check.
  let alertTriggered = false;
  let alertReason = null;
  if (ARGS.alertPct !== null) {
    if (!isFinite(ARGS.alertPct)) {
      console.error(`cost-diff: --alert-on-pct must be a finite number`);
      process.exit(2);
    }
    if (isFinite(total.pct) && total.pct > ARGS.alertPct) {
      alertTriggered = true;
      alertReason = `total spend grew ${total.pct.toFixed(2)}% (+$${total.delta.toFixed(6)}); threshold +${ARGS.alertPct}%`;
    }
  }
  if (!alertTriggered && ARGS.alertUsd !== null) {
    if (!isFinite(ARGS.alertUsd)) {
      console.error(`cost-diff: --alert-on-usd must be a finite number`);
      process.exit(2);
    }
    if (total.delta > ARGS.alertUsd) {
      alertTriggered = true;
      alertReason = `total spend grew $${total.delta.toFixed(6)}; threshold +$${ARGS.alertUsd.toFixed(2)}`;
    }
  }
  // iter 86 — per-class % thresholds. First class to breach wins.
  if (!alertTriggered && Object.keys(ARGS.alertClassPct).length > 0) {
    if (!tokenClassDeltas) {
      // Both snapshots lack byTokenClass — class threshold can't fire.
      // Don't error; the rule is silently inapplicable. CI gates that
      // depend on this should ensure their baseline format is current.
    } else {
      for (const [cls, threshold] of Object.entries(ARGS.alertClassPct)) {
        const row = tokenClassDeltas.find((c) => c.key === cls);
        if (row && isFinite(row.pct) && row.pct > threshold) {
          alertTriggered = true;
          alertReason = `\`${cls}\` tokens grew ${row.pct.toFixed(2)}% (+${row.delta.toLocaleString()} tok); threshold +${threshold}%`;
          break;
        }
      }
    }
  }

  const payload = {
    // iter 81 — git context surfaced when snapshots include it (cost-summary
    // started emitting `git` in iter 81 too). Older snapshots without git
    // metadata work fine; the fields are simply omitted.
    baseline: { path: ARGS.baseline, exportedAt: baseline.exportedAt, git: baseline.git || null, total_cost_usd: baseline.total_cost_usd },
    current:  { path: ARGS.current,  exportedAt: current.exportedAt,  git: current.git || null,  total_cost_usd: current.total_cost_usd },
    delta: {
      total_cost_usd: Math.round(total.delta * 1e6) / 1e6,
      total_pct: isFinite(total.pct) ? Math.round(total.pct * 100) / 100 : null,
      sessionCount: sessions.delta,
      sessionCount_pct: isFinite(sessions.pct) ? Math.round(sessions.pct * 100) / 100 : null,
    },
    byTier: tierDeltas,
    byModel: modelDeltas,
    byTokenClass: tokenClassDeltas,
    alert: (ARGS.alertPct !== null || ARGS.alertUsd !== null || Object.keys(ARGS.alertClassPct).length > 0) ? {
      triggered: alertTriggered,
      reason: alertReason,
      thresholdPct: ARGS.alertPct,
      thresholdUsd: ARGS.alertUsd,
      thresholdClassPct: Object.keys(ARGS.alertClassPct).length > 0 ? ARGS.alertClassPct : null,
    } : null,
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# cost-diff`);
    // iter 81 — surface git context when present so operators can correlate
    // diffs to commits without leaving the terminal.
    if (baseline.git || current.git) {
      const fmtGit = (g) => g
        ? `\`${g.shaShort}\` (${g.branch || 'detached'}${g.isDirty ? ', dirty' : ''})`
        : '_no git context_';
      console.log('');
      console.log(`_baseline: ${fmtGit(baseline.git)} → current: ${fmtGit(current.git)}_`);
    }
    console.log('');
    console.log(`| Metric | Baseline | Current | Delta | % |`);
    console.log(`|---|---:|---:|---:|---:|`);
    const dStr = total.delta >= 0 ? `+$${total.delta.toFixed(6)}` : `-$${Math.abs(total.delta).toFixed(6)}`;
    const pStr = isFinite(total.pct) ? `${total.pct.toFixed(2)}%` : 'new';
    console.log(`| **Total spend** | $${baseline.total_cost_usd.toFixed(6)} | $${current.total_cost_usd.toFixed(6)} | **${dStr}** | **${pStr}** |`);
    const sStr = sessions.delta >= 0 ? `+${sessions.delta}` : `${sessions.delta}`;
    const spStr = isFinite(sessions.pct) ? `${sessions.pct.toFixed(2)}%` : 'new';
    console.log(`| Sessions | ${baseline.sessionCount} | ${current.sessionCount} | ${sStr} | ${spStr} |`);
    console.log('');
    if (tierDeltas.length > 0) {
      console.log('## By tier');
      console.log('');
      console.log('| Tier | Baseline | Current | Delta | % | Status |');
      console.log('|---|---:|---:|---:|---:|:---:|');
      for (const t of tierDeltas) {
        const td = t.delta >= 0 ? `+$${t.delta.toFixed(6)}` : `-$${Math.abs(t.delta).toFixed(6)}`;
        const tp = isFinite(t.pct) ? `${t.pct.toFixed(2)}%` : (t.status === 'added' ? 'new' : '—');
        console.log(`| ${t.key} | $${t.baseline.toFixed(6)} | $${t.current.toFixed(6)} | ${td} | ${tp} | ${t.status} |`);
      }
      console.log('');
    }
    if (modelDeltas.length > 0) {
      console.log('## By model');
      console.log('');
      console.log('| Model | Baseline | Current | Delta | % | Status |');
      console.log('|---|---:|---:|---:|---:|:---:|');
      for (const m of modelDeltas) {
        const md = m.delta >= 0 ? `+$${m.delta.toFixed(6)}` : `-$${Math.abs(m.delta).toFixed(6)}`;
        const mp = isFinite(m.pct) ? `${m.pct.toFixed(2)}%` : (m.status === 'added' ? 'new' : '—');
        console.log(`| \`${m.key}\` | $${m.baseline.toFixed(6)} | $${m.current.toFixed(6)} | ${md} | ${mp} | ${m.status} |`);
      }
      console.log('');
    }
    // iter 85 — per-token-class delta surfaces cache_write growth driver.
    if (tokenClassDeltas && tokenClassDeltas.length > 0) {
      console.log('## By token class');
      console.log('');
      console.log('| Class | Baseline | Current | Delta | % | Status |');
      console.log('|---|---:|---:|---:|---:|:---:|');
      for (const c of tokenClassDeltas) {
        const cd = c.delta >= 0 ? `+${c.delta.toLocaleString()}` : c.delta.toLocaleString();
        const cp = isFinite(c.pct) ? `${c.pct.toFixed(2)}%` : (c.status === 'added' ? 'new' : '—');
        console.log(`| ${c.key} | ${c.baseline.toLocaleString()} | ${c.current.toLocaleString()} | ${cd} tok | ${cp} | ${c.status} |`);
      }
      console.log('');
      // Surface the cache-write-growth signal explicitly when present.
      const cacheWriteRow = tokenClassDeltas.find((c) => c.key === 'cache_write');
      if (cacheWriteRow && cacheWriteRow.delta > 0 && isFinite(cacheWriteRow.pct) && cacheWriteRow.pct > 50) {
        console.log(`_⚠ \`cache_write\` tokens grew ${cacheWriteRow.pct.toFixed(1)}% — that's the iter-82 cost driver. Investigate WHICH messages cache-wrote heavily via \`cost session --session-id <id>\`._`);
        console.log('');
      }
    }
    if (alertReason !== null) {
      if (alertTriggered) console.log(`⚠ **ALERT**: ${alertReason}`);
      else console.log(`✓ ${alertReason}`);
      console.log('');
    }
  }

  if (alertTriggered) process.exit(1);
}

main();

#!/usr/bin/env node
// cost-export — emit cost-tracking telemetry in formats consumable by
// external observability systems.
//
// Outputs:
//   --prometheus <path>   write Prometheus textfile-collector exposition
//   --webhook <url>       POST JSON payload (default Content-Type: application/json)
//   (no flag)             write JSON to stdout
//
// Env:
//   EXPORT_NAMESPACE=cost-tracking (default)
//   EXPORT_WEBHOOK_HEADER='Authorization: Bearer xxx'  optional, may repeat (comma-separated)
//   EXPORT_QUIET=1        suppress confirmation output (errors still printed)

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
// iter 73 — shared session-loader + memoryRetrieve. Iter 83 brought export.mjs
// into the consolidation (was missed in the original sweep).
import { memoryListAllKeys, memoryRetrieve, loadSessions } from './_sessions.mjs';

const NS = process.env.EXPORT_NAMESPACE || 'cost-tracking';

function gather() {
  const sessions = loadSessions(NS);
  const budgetKeys = memoryListAllKeys(NS).filter((k) => /^budget-config(-\d+)?$/.test(k)).sort().reverse();
  const budget = budgetKeys.length ? memoryRetrieve(NS, budgetKeys[0]) : null;
  const totalUsd = sessions.reduce((s, r) => s + (r.total_cost_usd || 0), 0);
  const byTier = { haiku: 0, sonnet: 0, opus: 0, unknown: 0 };
  // iter 83 — track tokens per (tier, type). Without this Prometheus
  // consumers can see "haiku spent $X" but can't slice by "cache_write
  // growth on opus" — the exact iter-82 driver. byTierTokens lets
  // Grafana panels split spend by class.
  const byTierTokens = {
    haiku:   { input: 0, output: 0, cache_write: 0, cache_read: 0 },
    sonnet:  { input: 0, output: 0, cache_write: 0, cache_read: 0 },
    opus:    { input: 0, output: 0, cache_write: 0, cache_read: 0 },
    unknown: { input: 0, output: 0, cache_write: 0, cache_read: 0 },
  };
  for (const r of sessions) {
    if (r.byTier) for (const [t, v] of Object.entries(r.byTier)) byTier[t] = (byTier[t] || 0) + v;
    if (r.byModel) {
      for (const slot of Object.values(r.byModel)) {
        const tier = slot.tier || 'unknown';
        if (!byTierTokens[tier]) byTierTokens[tier] = { input: 0, output: 0, cache_write: 0, cache_read: 0 };
        byTierTokens[tier].input       += slot.input_tokens || 0;
        byTierTokens[tier].output      += slot.output_tokens || 0;
        byTierTokens[tier].cache_write += slot.cache_creation_input_tokens || 0;
        byTierTokens[tier].cache_read  += slot.cache_read_input_tokens || 0;
      }
    }
  }
  return { sessions, budget, totalUsd, byTier, byTierTokens, exportedAt: new Date().toISOString() };
}

function escLabel(v) {
  return String(v ?? '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n');
}

function toPrometheus(data) {
  const lines = [];
  lines.push('# HELP cost_tracker_total_usd Total measured cost across all sessions in USD');
  lines.push('# TYPE cost_tracker_total_usd gauge');
  lines.push(`cost_tracker_total_usd ${data.totalUsd.toFixed(6)}`);
  lines.push('');
  lines.push('# HELP cost_tracker_tier_total_usd Total cost per tier across all sessions');
  lines.push('# TYPE cost_tracker_tier_total_usd gauge');
  for (const [tier, cost] of Object.entries(data.byTier)) {
    lines.push(`cost_tracker_tier_total_usd{tier="${escLabel(tier)}"} ${(cost || 0).toFixed(6)}`);
  }
  lines.push('');
  lines.push('# HELP cost_tracker_session_total_usd Cost per session in USD');
  lines.push('# TYPE cost_tracker_session_total_usd gauge');
  lines.push('# HELP cost_tracker_session_messages Assistant messages per session');
  lines.push('# TYPE cost_tracker_session_messages counter');
  for (const s of data.sessions) {
    const sid = (s.sessionId || '').slice(0, 8);
    lines.push(`cost_tracker_session_total_usd{session="${escLabel(sid)}"} ${(s.total_cost_usd || 0).toFixed(6)}`);
    lines.push(`cost_tracker_session_messages{session="${escLabel(sid)}"} ${s.messageCount || 0}`);
  }
  // iter 83 — per-tier-per-type token totals. Lets dashboards slice by:
  //   sum by (type) (cost_tracker_tokens_total)       — total cache_write everywhere
  //   sum by (tier) (cost_tracker_tokens_total)       — total tokens per tier
  //   cost_tracker_tokens_total{tier="opus",type="cache_write"}  — the iter-82 driver
  lines.push('');
  lines.push('# HELP cost_tracker_tokens_total Total tokens per tier and type (input/output/cache_write/cache_read)');
  lines.push('# TYPE cost_tracker_tokens_total counter');
  for (const [tier, perType] of Object.entries(data.byTierTokens || {})) {
    for (const [type, count] of Object.entries(perType)) {
      if (count > 0) {
        lines.push(`cost_tracker_tokens_total{tier="${escLabel(tier)}",type="${escLabel(type)}"} ${count}`);
      }
    }
  }
  if (data.budget?.budget_usd) {
    lines.push('');
    lines.push('# HELP cost_tracker_budget_usd Configured budget limit in USD');
    lines.push('# TYPE cost_tracker_budget_usd gauge');
    lines.push(`cost_tracker_budget_usd ${data.budget.budget_usd.toFixed(2)}`);
    lines.push('# HELP cost_tracker_budget_utilization Spent / budget ratio (0.0–∞)');
    lines.push('# TYPE cost_tracker_budget_utilization gauge');
    lines.push(`cost_tracker_budget_utilization ${(data.totalUsd / data.budget.budget_usd).toFixed(6)}`);
  }
  return lines.join('\n') + '\n';
}

async function postWebhook(url, data) {
  const headers = { 'Content-Type': 'application/json' };
  if (process.env.EXPORT_WEBHOOK_HEADER) {
    for (const h of process.env.EXPORT_WEBHOOK_HEADER.split(',')) {
      const [k, ...rest] = h.split(':');
      if (k && rest.length) headers[k.trim()] = rest.join(':').trim();
    }
  }
  const resp = await fetch(url, {
    method: 'POST', headers, body: JSON.stringify(data),
  });
  return { status: resp.status, ok: resp.ok };
}

function parseArgs() {
  const args = process.argv.slice(2);
  let prometheus = null, webhook = null;
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--prometheus') prometheus = args[++i];
    else if (args[i] === '--webhook') webhook = args[++i];
  }
  return { prometheus, webhook };
}

async function main() {
  const { prometheus, webhook } = parseArgs();
  const data = gather();
  if (process.env.EXPORT_QUIET !== '1') {
    console.error(`Exported ${data.sessions.length} sessions, total $${data.totalUsd.toFixed(2)}`);
  }
  if (prometheus) {
    mkdirSync(dirname(prometheus), { recursive: true });
    writeFileSync(prometheus, toPrometheus(data));
    if (process.env.EXPORT_QUIET !== '1') console.error(`Wrote Prometheus textfile: ${prometheus}`);
  }
  if (webhook) {
    const r = await postWebhook(webhook, data);
    if (!r.ok) {
      console.error(`Webhook POST failed: HTTP ${r.status}`);
      process.exit(1);
    }
    if (process.env.EXPORT_QUIET !== '1') console.error(`Webhook POST ok (HTTP ${r.status})`);
  }
  if (!prometheus && !webhook) {
    console.log(JSON.stringify(data, null, 2));
  }
}

main().catch((e) => { console.error('export failed:', e.message || e); process.exit(1); });

#!/usr/bin/env node
// cost-federation — aggregate per-peer federation_spend events into rolling
// 1h / 24h / 7d windows. Implements the consumer side of ADR-097 Phase 3.
//
// Phase 3 contract (from ADR-097):
//   Event: federation_spend = { peerId, taskId, tokensUsed, usdSpent, ts }
//   Storage: namespace `federation-spend`, key `fed-spend-<peerId>-<ts>`
//   Aggregation: per-peer rolling sums (1h, 24h, 7d)
//   Consumer: `cost-report` (this plugin), `breaker` (federation suspension)
//
// Phase 3 isn't landed upstream yet (federation_spend events aren't emitted).
// This script reads whatever IS in the namespace today (empty by default) and
// reports gracefully. The moment upstream emits, this works without changes.
//
// Usage:
//   node scripts/federation.mjs                       # markdown summary
//   FED_FORMAT=json node scripts/federation.mjs       # JSON
//   FED_NAMESPACE=federation-spend (default)

import { spawnNpxSync } from './_npx.mjs';

// ADR-100 / #1748 Issue 3 — CLI_CORE=1 routes to lite cli-core (~2s cold-cache).
// Federation aggregation is list+retrieve only on the federation-spend namespace.
const CLI_PKG = process.env.CLI_CORE === '1'
  ? '@claude-flow/cli-core@alpha'
  : '@claude-flow/cli@latest';

const NS = process.env.FED_NAMESPACE || 'federation-spend';

function memoryList() {
  const r = spawnNpxSync([
    CLI_PKG, 'memory', 'list',
    '--namespace', NS, '--format', 'json',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) return [];
  const m = /\[[\s\S]*\]/.exec(r.stdout || '');
  if (!m) return [];
  try { return JSON.parse(m[0]).map((e) => e.key).filter(Boolean); } catch { return []; }
}
function memoryRetrieve(key) {
  const r = spawnNpxSync([
    CLI_PKG, 'memory', 'retrieve',
    '--namespace', NS, '--key', key, '--value-only',
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) return null;
  try { return JSON.parse((r.stdout || '').trim()); } catch { return null; }
}

function gather() {
  const keys = memoryList();
  const events = keys
    .filter((k) => k.startsWith('fed-spend-'))
    .map(memoryRetrieve)
    .filter(Boolean);
  return events;
}

function bucket(events) {
  const now = Date.now();
  const h = 3600 * 1000;
  const day = 24 * h;
  const perPeer = {};
  for (const e of events) {
    const peer = e.peerId || 'unknown';
    const ts = e.ts ? new Date(e.ts).getTime() : 0;
    if (!perPeer[peer]) perPeer[peer] = {
      peer, count1h: 0, count24h: 0, count7d: 0,
      tokens1h: 0, tokens24h: 0, tokens7d: 0,
      usd1h: 0, usd24h: 0, usd7d: 0,
      total: { tokens: 0, usd: 0, count: 0 },
    };
    const p = perPeer[peer];
    const tokens = e.tokensUsed || 0;
    const usd = e.usdSpent || 0;
    p.total.tokens += tokens; p.total.usd += usd; p.total.count++;
    if (ts && now - ts < 7 * day) { p.count7d++; p.tokens7d += tokens; p.usd7d += usd; }
    if (ts && now - ts < day)     { p.count24h++; p.tokens24h += tokens; p.usd24h += usd; }
    if (ts && now - ts < h)       { p.count1h++; p.tokens1h += tokens; p.usd1h += usd; }
  }
  return Object.values(perPeer).sort((a, b) => b.usd24h - a.usd24h);
}

function fmtUsd(n) { return `$${(n || 0).toFixed(4)}`; }

function main() {
  const events = gather();
  const peers = bucket(events);
  const totalUsd24h = peers.reduce((s, p) => s + p.usd24h, 0);

  if (process.env.FED_FORMAT === 'json') {
    console.log(JSON.stringify({
      eventCount: events.length,
      peers,
      totalUsd24h,
      phase3Active: events.length > 0,
    }, null, 2));
    return;
  }

  console.log(`# cost-federation — per-peer federation_spend rolling windows`);
  console.log('');
  console.log(`Namespace: \`${NS}\`  ·  Events: ${events.length}  ·  Peers: ${peers.length}`);
  if (events.length === 0) {
    console.log('');
    console.log('> No federation_spend events found. Phase 3 of ADR-097 is not yet emitting.');
    console.log('> This skill is the consumer-side wiring; it will activate the moment upstream');
    console.log('> publishes events with shape `{peerId, taskId, tokensUsed, usdSpent, ts}` to');
    console.log('> the `' + NS + '` namespace.');
    return;
  }
  console.log('');
  console.log(`Total 24h spend: **${fmtUsd(totalUsd24h)}**`);
  console.log('');
  console.log('| Peer | 1h count | 1h $ | 24h count | 24h $ | 7d count | 7d $ |');
  console.log('|---|---:|---:|---:|---:|---:|---:|');
  for (const p of peers) {
    console.log(`| \`${p.peer}\` | ${p.count1h} | ${fmtUsd(p.usd1h)} | ${p.count24h} | ${fmtUsd(p.usd24h)} | ${p.count7d} | ${fmtUsd(p.usd7d)} |`);
  }
  console.log('');
  console.log('## Suspension threshold check (ADR-097 default $5/24h)');
  console.log('');
  const SUSPEND_THRESHOLD = parseFloat(process.env.FED_SUSPEND_THRESHOLD_USD || '5.0');
  const offenders = peers.filter((p) => p.usd24h > SUSPEND_THRESHOLD);
  if (offenders.length === 0) {
    console.log(`No peer exceeds the $${SUSPEND_THRESHOLD.toFixed(2)}/24h threshold.`);
  } else {
    console.log(`**⚠ ${offenders.length} peer(s) exceed $${SUSPEND_THRESHOLD.toFixed(2)}/24h** (Phase 2 breaker would suspend):`);
    for (const p of offenders) console.log(`- \`${p.peer}\` — 24h $${p.usd24h.toFixed(2)}`);
  }
}

main();

#!/usr/bin/env node
// cost-health — composition skill: runs all four CI-gate checks in parallel
// and surfaces a single combined health status with max exit code.
//
// Each underlying check answers a different question; together they form
// a complete spend health picture:
//
//   budget-check  (reactive)    "have we crossed the budget?"
//   burn          (trend)       "is daily burn accelerating?"
//   anomaly       (point)       "is any specific session an outlier?"
//   projection    (predictive)  "when will we hit the budget?"
//
// USAGE
//   node scripts/health.mjs                                    # default thresholds
//   node scripts/health.mjs --alert-acceleration 50            # burn threshold
//   node scripts/health.mjs --alert-outliers 1                 # anomaly threshold
//   node scripts/health.mjs --alert-days-to-exhaust 7          # projection threshold
//   node scripts/health.mjs --format json
//
// Default thresholds are set to "would you want to know about this on Slack?":
//   - burn:       +100% (latest day spent 2× the prior weekly mean)
//   - anomaly:    ≥1 outlier (any single session > 3.5σ from median)
//   - projection: <14d until 100% budget (only fires when budget is set)
//   - budget:     HARD_STOP at 100% (the budget-check default)
//
// EXIT CODE = max(component exits). If ANY subcheck failed, the gate fails.
//
// Env: HEALTH_QUIET=1, HEALTH_BUDGET_PERIOD=today|week|month|all,
//      HEALTH_NAMESPACE=cost-tracking (forwarded to each subcheck).

import { spawn } from 'node:child_process';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));

const ARGS = (() => {
  const a = {
    alertAcceleration: 100,   // burn  — +100% bucket vs prior mean
    alertOutliers: 1,         // anomaly — any outlier fails
    alertDaysToExhaust: 14,   // projection — < 14d to 100% budget
    format: 'table',
    skip: new Set(),          // --skip burn,anomaly  to disable subchecks
  };
  if (process.env.HEALTH_QUIET === '1') a.format = 'json';
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--alert-acceleration') a.alertAcceleration = parseFloat(process.argv[++i]);
    else if (v === '--alert-outliers') a.alertOutliers = parseInt(process.argv[++i], 10);
    else if (v === '--alert-days-to-exhaust') a.alertDaysToExhaust = parseFloat(process.argv[++i]);
    else if (v === '--format') a.format = process.argv[++i];
    else if (v === '--skip') {
      for (const s of (process.argv[++i] || '').split(',')) a.skip.add(s.trim());
    }
  }
  return a;
})();

function runScript(name, scriptFile, scriptArgs, jsonViaEnv) {
  // Most scripts take `--format json` as a flag. budget.mjs uses
  // positional subcommands + BUDGET_QUIET=1 env to opt into JSON. The
  // jsonViaEnv parameter lets the caller pick which mechanism to use.
  const args = jsonViaEnv
    ? [scriptFile, ...scriptArgs]
    : [scriptFile, ...scriptArgs, '--format', 'json'];
  const env = jsonViaEnv
    ? { ...process.env, [jsonViaEnv]: '1' }
    : process.env;
  return new Promise((resolve) => {
    const p = spawn('node', args, { stdio: ['ignore', 'pipe', 'pipe'], env });
    let stdout = '';
    let stderr = '';
    p.stdout.on('data', (d) => { stdout += d.toString(); });
    p.stderr.on('data', (d) => { stderr += d.toString(); });
    p.on('close', (code) => {
      let json = null;
      const m = /\{[\s\S]*\}/.exec(stdout);
      if (m) {
        try { json = JSON.parse(m[0]); } catch { /* leave null */ }
      }
      resolve({ name, exitCode: code ?? 0, json, stderr: stderr.slice(0, 300) });
    });
    p.on('error', (err) => {
      resolve({ name, exitCode: 127, json: null, stderr: err.message });
    });
  });
}

async function main() {
  const budgetPeriod = process.env.HEALTH_BUDGET_PERIOD || 'all';

  const tasks = [];
  if (!ARGS.skip.has('budget')) {
    tasks.push(runScript('budget', join(SCRIPTS_DIR, 'budget.mjs'), ['check'], 'BUDGET_QUIET'));
  }
  if (!ARGS.skip.has('burn')) {
    tasks.push(runScript('burn', join(SCRIPTS_DIR, 'burn.mjs'), [
      '--alert-on-acceleration-pct', String(ARGS.alertAcceleration),
    ]));
  }
  if (!ARGS.skip.has('anomaly')) {
    tasks.push(runScript('anomaly', join(SCRIPTS_DIR, 'anomaly.mjs'), [
      '--alert-on-outliers', String(ARGS.alertOutliers),
    ]));
  }
  if (!ARGS.skip.has('projection')) {
    tasks.push(runScript('projection', join(SCRIPTS_DIR, 'projection.mjs'), []));
  }

  // Run in parallel — each spawns its own npx CLI shellout.
  const results = await Promise.all(tasks);

  // Projection has no built-in exit code, so derive a synthetic one from
  // days-until-100%-budget-exhaustion.
  const projectionResult = results.find((r) => r.name === 'projection');
  let projectionExit = 0;
  let projectionDays = null;
  if (projectionResult?.json?.budget?.exhaustion) {
    const hundred = projectionResult.json.budget.exhaustion.find((e) => e.thresholdPct === 100);
    if (hundred?.daysUntilReached !== undefined && hundred.daysUntilReached !== null) {
      projectionDays = hundred.daysUntilReached;
      if (hundred.daysUntilReached < ARGS.alertDaysToExhaust) {
        projectionExit = 1;
      }
    }
    projectionResult.exitCode = projectionExit;
  } else if (projectionResult) {
    // No budget configured or no data — projection is "OK" by default.
    projectionResult.exitCode = 0;
  }

  const maxExit = Math.max(...results.map((r) => r.exitCode));

  const payload = {
    config: {
      alertAcceleration: ARGS.alertAcceleration,
      alertOutliers: ARGS.alertOutliers,
      alertDaysToExhaust: ARGS.alertDaysToExhaust,
      budgetPeriod,
      skipped: [...ARGS.skip],
    },
    checks: results.map((r) => ({
      name: r.name,
      exitCode: r.exitCode,
      ok: r.exitCode === 0,
      summary: summarize(r),
    })),
    overall: {
      ok: maxExit === 0,
      exitCode: maxExit,
    },
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
  } else {
    console.log(`# cost-health`);
    console.log('');
    const badge = maxExit === 0 ? '✓ HEALTHY' : '⚠ UNHEALTHY';
    console.log(`**Overall**: ${badge} (max exit code ${maxExit})`);
    console.log('');
    console.log('| Check | Status | Detail |');
    console.log('|---|:---:|---|');
    for (const r of results) {
      const status = r.exitCode === 0 ? '✓' : '⚠';
      console.log(`| \`${r.name}\` | ${status} | ${summarize(r)} |`);
    }
    if (ARGS.skip.size > 0) {
      console.log('');
      console.log(`_Skipped: ${[...ARGS.skip].join(', ')}_`);
    }
    console.log('');
    console.log(`_Run \`cost <check>\` for the full detail of any failing leg._`);
    console.log('');
  }

  process.exit(maxExit);
}

function summarize(r) {
  if (!r) return 'no result';
  if (r.exitCode === 127 || !r.json) {
    return `**error** (exit ${r.exitCode}${r.stderr ? `: ${r.stderr.slice(0, 80)}` : ''})`;
  }
  const j = r.json;
  switch (r.name) {
    case 'budget': {
      // budget.mjs returns { error: 'no budget configured', totalSpend, recordCount }
      // when no budget is set; otherwise { level, utilization_pct, budget_usd, spent_usd }.
      if (j.error === 'no budget configured') {
        const spend = typeof j.totalSpend === 'number' ? `$${j.totalSpend.toFixed(2)}` : '—';
        return `no budget set (${spend} measured spend; run \`cost budget set <usd>\` to enable)`;
      }
      const level = j.level || 'OK';
      const util = (typeof j.utilization_pct === 'number') ? `${j.utilization_pct.toFixed(1)}%` : '—';
      const budget = (typeof j.budget_usd === 'number') ? `$${j.budget_usd.toFixed(2)}` : '—';
      return `${level} — ${util} of ${budget} budget consumed`;
    }
    case 'burn': {
      const d = j.delta?.deltaPct;
      const triggered = j.alert?.triggered;
      const reason = j.alert?.reason || '';
      if (triggered) return `**ALERT** ${d?.toFixed(1)}% acceleration: ${reason.slice(0, 100)}`;
      return `delta ${d === null ? 'n/a' : (d?.toFixed?.(1) ?? '0') + '%'} — within ±${ARGS.alertAcceleration}%`;
    }
    case 'anomaly': {
      const n = j.outliers?.length ?? 0;
      const triggered = j.alert?.triggered;
      if (triggered) return `**ALERT** ${n} outlier session(s) detected (|z|>${j.filters?.threshold ?? 3.5})`;
      if (!j.sufficient) return `insufficient data (${j.reason || 'n<3'})`;
      return `${n} outlier(s) — under threshold ≥${ARGS.alertOutliers}`;
    }
    case 'projection': {
      if (!j.budget) return 'no budget configured — skipping forward-look';
      const hundred = j.budget.exhaustion?.find((e) => e.thresholdPct === 100);
      if (!hundred || hundred.daysUntilReached === null || hundred.daysUntilReached === undefined) {
        return 'no spend rate yet — cannot project';
      }
      const d = hundred.daysUntilReached;
      if (d < ARGS.alertDaysToExhaust) return `**ALERT** ${d.toFixed(1)}d to 100% budget (threshold <${ARGS.alertDaysToExhaust}d)`;
      return `${d.toFixed(1)}d to 100% budget — over ${ARGS.alertDaysToExhaust}d horizon`;
    }
    default:
      return `exit ${r.exitCode}`;
  }
}

main();

#!/usr/bin/env node
// cost-outcome — thin wrapper around `hooks model-outcome` so cost-optimize
// recommendations can be emitted as pre-formatted shell commands. The agent
// (or human) runs this once per applied recommendation and the router learns.
//
// Usage:
//   node scripts/outcome.mjs <task-description> <model> <outcome>
//     outcome ∈ { success, escalated, failure }
//
// Example:
//   node scripts/outcome.mjs "format imports" haiku success
//   node scripts/outcome.mjs "design auth flow" sonnet escalated
//
// Why a wrapper: `hooks model-outcome` takes `-t -m -o` and quoting through
// shell pipelines is error-prone. This script uses spawnSync with explicit
// argv so a task description with quotes/newlines is preserved.

import { spawnNpxSync } from './_npx.mjs';

const ALLOWED = new Set(['success', 'escalated', 'failure']);

function main() {
  const [task, model, outcome] = process.argv.slice(2);
  if (!task || !model || !outcome) {
    console.error('usage: outcome.mjs <task-description> <model> <outcome>');
    console.error('  outcome ∈ {success, escalated, failure}');
    process.exit(2);
  }
  if (!ALLOWED.has(outcome)) {
    console.error(`invalid outcome '${outcome}' — must be one of: success, escalated, failure`);
    process.exit(2);
  }
  const r = spawnNpxSync([
    '@claude-flow/cli@latest', 'hooks', 'model-outcome',
    '-t', task, '-m', model, '-o', outcome,
  ], { stdio: 'inherit', shell: process.platform === 'win32' });
  if (r.status !== 0) {
    console.error(`emit failed (exit ${r.status})`);
    process.exit(r.status || 1);
  }
}

main();

#!/usr/bin/env node
// cost-projection — forward-looking spend extrapolation.
//
// Iter 41 of ADR-149 router work added a similar tool for routing decisions;
// this is the cost-tracker equivalent for session-level spend.
//
// METHOD
//   1. Read `cost-tracking` namespace session records (same source as budget.mjs)
//   2. Filter to a measurement window (default last 7d on capturedAt/startedAt)
//   3. Compute USD-per-day rate from that window
//   4. Linear-extrapolate to 7d / 30d / 90d / 365d horizons
//   5. If a budget is configured: compute "days until 75% / 90% / 100% consumed"
//
// Pairs with `cost budget check` (reactive alerts) to give operators a
// PREDICTIVE view — finance/SREs want to know "when will we hit the cap?"
// not just "we hit the cap".
//
// USAGE
//   node scripts/projection.mjs                           # default 7d window
//   node scripts/projection.mjs --window 24h              # extrapolate from last day
//   node scripts/projection.mjs --horizons 7d,30d,90d     # custom horizons
//   node scripts/projection.mjs --format json             # pipe to dashboards
//
// Env: PROJECTION_NAMESPACE (default cost-tracking)
//      PROJECTION_QUIET=1 → JSON only (alias for --format json)

// iter 73 — shared session-loader + memoryRetrieve (was duplicated across 6 scripts).
import {
  loadSessions,
  memoryRetrieve,
  memoryListAllKeys,
  sessionTs,
  parseDurationMs,
} from './_sessions.mjs';

const NS = process.env.PROJECTION_NAMESPACE || 'cost-tracking';

const ARGS = (() => {
  const a = { window: '7d', horizons: '7d,30d,90d,365d', format: 'table' };
  if (process.env.PROJECTION_QUIET === '1') a.format = 'json';
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--window') a.window = process.argv[++i];
    else if (v === '--horizons') a.horizons = process.argv[++i];
    else if (v === '--format') a.format = process.argv[++i];
  }
  return a;
})();

// ----------------------------------------------------------------------------
// Budget config — mirror budget.mjs latest-stamp resolution.
// ----------------------------------------------------------------------------
function getBudgetConfig() {
  const stamped = memoryListAllKeys(NS)
    .filter((k) => /^budget-config-\d+$/.test(k))
    .sort();
  const latest = stamped[stamped.length - 1];
  if (latest) return memoryRetrieve(NS, latest);
  // Fallback: plain budget-config key (legacy / pre-stamping)
  return memoryRetrieve(NS, 'budget-config');
}

// ----------------------------------------------------------------------------
// Time math
// ----------------------------------------------------------------------------
function formatDays(ms) {
  if (!Number.isFinite(ms) || ms <= 0) return 'never';
  const days = ms / 86400_000;
  if (days < 1) return `${(days * 24).toFixed(1)} hours`;
  if (days < 60) return `${days.toFixed(1)} days`;
  return `${(days / 30).toFixed(1)} months`;
}

// ----------------------------------------------------------------------------
// Main
// ----------------------------------------------------------------------------
function main() {
  const windowMs = parseDurationMs(ARGS.window);
  if (!windowMs) {
    console.error(`projection: --window must be N(h|d|w|m); got "${ARGS.window}"`);
    process.exit(2);
  }

  const horizonSpecs = ARGS.horizons.split(',').map((s) => s.trim()).filter(Boolean);
  for (const spec of horizonSpecs) {
    if (!parseDurationMs(spec)) {
      console.error(`projection: invalid horizon "${spec}"`);
      process.exit(2);
    }
  }

  // Read all sessions (shared loader, iter 73).
  const records = loadSessions(NS);

  // Filter by measurement window — use capturedAt if present, else startedAt.
  const cutoffMs = Date.now() - windowMs;
  const windowed = records.filter((r) => sessionTs(r) >= cutoffMs);
  const windowSpend = windowed.reduce((s, r) => s + (r.total_cost_usd || 0), 0);
  const windowDays = windowMs / 86400_000;
  const usdPerDay = windowSpend / windowDays;

  // Compute total all-time spend (for budget consumed-so-far math).
  const totalSpend = records.reduce((s, r) => s + (r.total_cost_usd || 0), 0);

  const budget = getBudgetConfig();
  const budgetUsd = budget && Number.isFinite(budget.budget_usd) ? budget.budget_usd : null;

  // Horizons: linear extrapolation
  const horizons = horizonSpecs.map((spec) => {
    const ms = parseDurationMs(spec);
    const projectedUsd = usdPerDay * (ms / 86400_000);
    return {
      horizon: spec,
      days: ms / 86400_000,
      projectedSpendUsd: Math.round(projectedUsd * 1e6) / 1e6,
    };
  });

  // Budget exhaustion projections (when configured + rate > 0).
  let budgetExhaustion = null;
  if (budgetUsd !== null && usdPerDay > 0) {
    const targets = [0.75, 0.90, 1.00];
    budgetExhaustion = targets.map((pct) => {
      const targetUsd = budgetUsd * pct;
      const remainingUsd = Math.max(0, targetUsd - totalSpend);
      const daysUntil = remainingUsd / usdPerDay;
      const exhaustionMs = daysUntil * 86400_000;
      return {
        thresholdPct: pct * 100,
        targetUsd: Math.round(targetUsd * 1e6) / 1e6,
        remainingUsd: Math.round(remainingUsd * 1e6) / 1e6,
        daysUntilReached: Math.round(daysUntil * 10) / 10,
        humanReadable: formatDays(exhaustionMs),
        alreadyReached: totalSpend >= targetUsd,
      };
    });
  }

  const payload = {
    namespace: NS,
    measurementWindow: ARGS.window,
    measurement: {
      sessionsInWindow: windowed.length,
      windowSpendUsd: Math.round(windowSpend * 1e6) / 1e6,
      windowDays,
      usdPerDay: Math.round(usdPerDay * 1e6) / 1e6,
    },
    allTime: {
      sessionsTotal: records.length,
      totalSpendUsd: Math.round(totalSpend * 1e6) / 1e6,
    },
    horizons,
    budget: budgetUsd !== null ? {
      configuredUsd: budgetUsd,
      utilizationPct: budgetUsd > 0 ? Math.round((totalSpend / budgetUsd) * 10000) / 100 : 0,
      exhaustion: budgetExhaustion,
    } : null,
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
    return;
  }

  // Markdown / human output.
  console.log(`# cost-projection (window: ${ARGS.window})`);
  console.log('');
  console.log(`| Metric | Value |`);
  console.log(`|---|---:|`);
  console.log(`| Sessions in window | ${windowed.length} |`);
  console.log(`| Window spend | $${windowSpend.toFixed(6)} |`);
  console.log(`| Days in window | ${windowDays.toFixed(1)} |`);
  console.log(`| **USD per day** | **$${usdPerDay.toFixed(6)}** |`);
  console.log(`| All-time spend | $${totalSpend.toFixed(6)} across ${records.length} sessions |`);
  console.log('');
  console.log('## Projected spend (linear extrapolation)');
  console.log('');
  console.log('| Horizon | Days | Projected spend |');
  console.log('|---|---:|---:|');
  for (const h of horizons) {
    console.log(`| ${h.horizon} | ${h.days} | $${h.projectedSpendUsd.toFixed(4)} |`);
  }
  console.log('');
  if (budgetExhaustion) {
    console.log(`## Budget exhaustion ($${budgetUsd.toFixed(2)} configured)`);
    console.log('');
    console.log('| Threshold | Target | Remaining | Time at current rate |');
    console.log('|---|---:|---:|---|');
    for (const ex of budgetExhaustion) {
      const status = ex.alreadyReached ? '**ALREADY REACHED**' : ex.humanReadable;
      console.log(`| ${ex.thresholdPct.toFixed(0)}% | $${ex.targetUsd.toFixed(2)} | $${ex.remainingUsd.toFixed(2)} | ${status} |`);
    }
    console.log('');
    console.log('Assumes the current rate holds. Re-run after large workload shifts.');
  } else if (budgetUsd === null) {
    console.log(`_No budget configured — set one with \`cost budget set <usd>\` to see exhaustion projections._`);
    console.log('');
  } else if (usdPerDay === 0) {
    console.log(`_No spend in measurement window — projection cannot extrapolate from zero. Widen --window or record more sessions._`);
    console.log('');
  }
}

main();

#!/usr/bin/env node
/**
 * ruflo-hook.cjs — cross-platform Windows shim for cost-tracker's Stop hook (#2132)
 *
 * The cost-tracker hooks.json declares `"_platform": "posix"` because its
 * Stop hook uses bash:
 *
 *   /bin/bash -c 'TRACK_QUIET=1 node "${CLAUDE_PLUGIN_ROOT}/scripts/track.mjs" >/dev/null 2>&1 || true'
 *
 * On Windows, `ruflo init` writes a `.claude/settings.json` that overrides
 * the Stop hook to invoke this shim instead — `node ruflo-hook.cjs` —
 * so cost tracking continues to capture session data without bash.
 *
 * Behaviour mirrors the bash hook:
 *   1. Reads hook event payload from stdin (best effort — discarded).
 *   2. Spawns track.mjs with TRACK_QUIET=1 and swallows all output.
 *   3. Always exits 0 — telemetry is best-effort, must NEVER block a turn.
 *   4. Times out at 30s so a hung track.mjs can't stall session shutdown.
 *
 * Usage: node ruflo-hook.cjs [hook-args ignored]
 */

'use strict';

const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

function done() {
  process.exit(0);
}

// Best-effort drain of stdin so the pipe doesn't EPIPE on the parent
try {
  fs.readFileSync(0);
} catch {
  /* ignore */
}

// CLAUDE_PLUGIN_ROOT is set by Claude Code; fall back to this script's parent
const pluginRoot = process.env.CLAUDE_PLUGIN_ROOT
  || path.resolve(__dirname, '..');
const trackScript = path.join(pluginRoot, 'scripts', 'track.mjs');

if (!fs.existsSync(trackScript)) {
  // Plugin layout drifted — exit clean, never block the turn
  done();
}

spawnSync(process.execPath, [trackScript], {
  env: { ...process.env, TRACK_QUIET: '1' },
  stdio: 'ignore',
  timeout: 30_000,
});

done();

#!/usr/bin/env node
// cost-session — per-message cost breakdown for a single session.
//
// cost-anomaly identifies WHICH sessions are outliers ($spend distribution).
// cost-conversation lists ALL sessions and their totals.
// This skill answers: given ONE session (especially an outlier), WHICH
// MESSAGES within it were expensive?
//
// METHOD
//   1. Resolve the session jsonl: `--session-id <id>` or `--latest` (default).
//   2. Parse all assistant messages with `usage` blocks.
//   3. Cost each message via the shared PRICING table (_prices.mjs).
//   4. Sort by cost descending, surface top-N.
//   5. Output: total + per-message breakdown + cost-percentile context.
//
// Pairs with cost-anomaly: when a session is flagged as a >3.5σ outlier,
// `cost session --session-id <flagged-id>` shows the expensive messages.
//
// USAGE
//   node scripts/session.mjs                           # latest session (default --top 20)
//   node scripts/session.mjs --session-id <id>         # by id (searches all project dirs)
//   node scripts/session.mjs --top 10                  # show top N
//   node scripts/session.mjs --since 2026-06-15        # filter by ISO timestamp
//   node scripts/session.mjs --format json
//
// EXIT CODES
//   0  success
//   2  config error or session not found

import { readdirSync, readFileSync, statSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';
// iter 73 — shared PRICING + cost helpers.
import { modelTier, costForUsage } from './_prices.mjs';

const PROJECTS_DIR = join(homedir(), '.claude', 'projects');

const ARGS = (() => {
  const a = { sessionId: null, top: 20, since: null, format: 'table' };
  if (process.env.SESSION_QUIET === '1') a.format = 'json';
  for (let i = 2; i < process.argv.length; i++) {
    const v = process.argv[i];
    if (v === '--session-id') a.sessionId = process.argv[++i];
    else if (v === '--top') a.top = parseInt(process.argv[++i], 10);
    else if (v === '--since') a.since = process.argv[++i];
    else if (v === '--format') a.format = process.argv[++i];
    else if (v === '--latest') a.sessionId = null;
  }
  return a;
})();

function listAllJsonls() {
  if (!existsSync(PROJECTS_DIR)) return [];
  const out = [];
  for (const proj of readdirSync(PROJECTS_DIR)) {
    const projDir = join(PROJECTS_DIR, proj);
    let stat;
    try { stat = statSync(projDir); } catch { continue; }
    if (!stat.isDirectory()) continue;
    let entries;
    try { entries = readdirSync(projDir); } catch { continue; }
    for (const f of entries) {
      if (!f.endsWith('.jsonl')) continue;
      const path = join(projDir, f);
      let st;
      try { st = statSync(path); } catch { continue; }
      out.push({ path, mtime: st.mtimeMs, project: proj });
    }
  }
  return out;
}

function findSessionJsonl(sessionId) {
  const all = listAllJsonls();
  if (!sessionId) {
    // --latest: pick the most-recently-modified jsonl
    if (all.length === 0) return null;
    return all.sort((a, b) => b.mtime - a.mtime)[0];
  }
  // Scan each jsonl for the sessionId. Most jsonls contain a single
  // sessionId across all their messages, so reading the first line is
  // usually enough — but fall back to a full scan if needed.
  for (const f of all) {
    let head;
    try { head = readFileSync(f.path, 'utf-8').split('\n').slice(0, 5).join('\n'); }
    catch { continue; }
    if (head.includes(`"sessionId":"${sessionId}"`)) return f;
  }
  return null;
}

function summarizeMessages(jsonlPath) {
  const text = readFileSync(jsonlPath, 'utf-8');
  const lines = text.split('\n').filter(Boolean);
  const messages = [];
  let sinceMs = null;
  if (ARGS.since) {
    const t = Date.parse(ARGS.since);
    if (Number.isFinite(t)) sinceMs = t;
  }
  for (const line of lines) {
    let m;
    try { m = JSON.parse(line); } catch { continue; }
    if (m.type !== 'assistant' || !m.message?.usage) continue;
    if (sinceMs !== null && m.timestamp && new Date(m.timestamp).getTime() < sinceMs) continue;
    const model = m.message.model || 'unknown';
    const tier = modelTier(model);
    const u = m.message.usage;
    const cost = costForUsage(tier, u);
    messages.push({
      timestamp: m.timestamp || null,
      model,
      tier,
      input_tokens: u.input_tokens || 0,
      output_tokens: u.output_tokens || 0,
      cache_creation_input_tokens: u.cache_creation_input_tokens || 0,
      cache_read_input_tokens: u.cache_read_input_tokens || 0,
      cost_usd: cost,
    });
  }
  return messages;
}

function main() {
  if (!Number.isInteger(ARGS.top) || ARGS.top < 1) {
    console.error(`cost-session: --top must be a positive integer; got ${ARGS.top}`);
    process.exit(2);
  }
  const sessionFile = findSessionJsonl(ARGS.sessionId);
  if (!sessionFile) {
    console.error(`cost-session: ${ARGS.sessionId ? `no session matches id "${ARGS.sessionId}"` : 'no sessions found'}`);
    process.exit(2);
  }
  const messages = summarizeMessages(sessionFile.path);
  if (messages.length === 0) {
    if (ARGS.format === 'json') {
      console.log(JSON.stringify({
        sessionFile: sessionFile.path,
        sessionId: ARGS.sessionId,
        messageCount: 0,
        total_cost_usd: 0,
        messages: [],
        topByMessage: [],
        generatedAt: new Date().toISOString(),
      }, null, 2));
    } else {
      console.log(`# cost-session\n\n_No costed assistant messages in \`${sessionFile.path}\`._\n`);
    }
    return;
  }

  const total = messages.reduce((s, m) => s + m.cost_usd, 0);
  const sorted = messages.slice().sort((a, b) => b.cost_usd - a.cost_usd);
  const top = sorted.slice(0, ARGS.top);

  // Cost percentile context — p50/p90/p99 of message costs.
  const ascending = messages.map((m) => m.cost_usd).sort((a, b) => a - b);
  const pct = (q) => {
    const idx = Math.floor(q * (ascending.length - 1));
    return ascending[idx] || 0;
  };
  const percentiles = { p50: pct(0.5), p90: pct(0.9), p99: pct(0.99) };

  const payload = {
    sessionFile: sessionFile.path,
    sessionId: ARGS.sessionId,
    filters: { top: ARGS.top, since: ARGS.since },
    messageCount: messages.length,
    total_cost_usd: Math.round(total * 1e6) / 1e6,
    percentiles: {
      p50_cost_usd: Math.round(percentiles.p50 * 1e6) / 1e6,
      p90_cost_usd: Math.round(percentiles.p90 * 1e6) / 1e6,
      p99_cost_usd: Math.round(percentiles.p99 * 1e6) / 1e6,
    },
    topByMessage: top.map((m, i) => ({
      rank: i + 1,
      timestamp: m.timestamp,
      model: m.model,
      tier: m.tier,
      input_tokens: m.input_tokens,
      output_tokens: m.output_tokens,
      // iter 82 — surface cache_creation_input_tokens too. Without it,
      // big cache-write costs (e.g. opus @ 881K tokens = $16) look like
      // a 569-token output costing $16, which is misleading.
      cache_creation_input_tokens: m.cache_creation_input_tokens,
      cache_read_input_tokens: m.cache_read_input_tokens,
      cost_usd: Math.round(m.cost_usd * 1e6) / 1e6,
      pctOfSession: total > 0 ? Math.round((m.cost_usd / total) * 10000) / 100 : 0,
    })),
    generatedAt: new Date().toISOString(),
  };

  if (ARGS.format === 'json') {
    console.log(JSON.stringify(payload, null, 2));
    return;
  }

  console.log(`# cost-session — ${sessionFile.path.split('/').pop()}`);
  console.log('');
  console.log(`| Metric | Value |`);
  console.log(`|---|---:|`);
  console.log(`| Session file | \`${sessionFile.path}\` |`);
  console.log(`| Assistant messages | ${messages.length} |`);
  console.log(`| **Total cost** | **$${total.toFixed(6)}** |`);
  console.log(`| Median (p50) message | $${percentiles.p50.toFixed(6)} |`);
  console.log(`| p90 message | $${percentiles.p90.toFixed(6)} |`);
  console.log(`| p99 message | $${percentiles.p99.toFixed(6)} |`);
  console.log('');
  console.log(`## Top ${Math.min(ARGS.top, messages.length)} most expensive messages`);
  console.log('');
  console.log('| # | Timestamp | Model | Tier | In | Out | Cache W | Cache R | Cost | % session |');
  console.log('|---:|---|---|---|---:|---:|---:|---:|---:|---:|');
  for (const m of payload.topByMessage) {
    const tsShort = m.timestamp ? m.timestamp.slice(0, 19).replace('T', ' ') : '—';
    const modelShort = m.model.length > 30 ? m.model.slice(0, 27) + '…' : m.model;
    console.log(`| ${m.rank} | ${tsShort} | \`${modelShort}\` | ${m.tier} | ${m.input_tokens} | ${m.output_tokens} | ${m.cache_creation_input_tokens} | ${m.cache_read_input_tokens} | $${m.cost_usd.toFixed(6)} | ${m.pctOfSession.toFixed(2)}% |`);
  }
  console.log('');
  if (top[0].cost_usd > percentiles.p99 * 2) {
    console.log(`_The top message is >2× the p99 of this session — that's an in-session outlier; check the prompt content._`);
    console.log('');
  }
}

main();

#!/usr/bin/env node
// cost-summary — programmatic single-shot dump of all cost-tracking data.
// Other plugins / scripts can shell out: `node summary.mjs --format json` and
// parse the result. This is the plugin-local equivalent of the MCP tool
// `cost_summary` that ADR-0002 considered but explicitly deferred (would
// require modifying @claude-flow/cli source — out of scope for this plugin).
//
// Output (JSON shape — stable contract for consumers):
// {
//   exportedAt: ISO,
//   total_cost_usd: number,
//   sessionCount: number,
//   conversationCount: number,    // alias of sessionCount
//   byTier: { haiku, sonnet, opus, unknown }: USD,
//   byModel: { <model>: { tier, cost_usd, messages, ... } },
//   topSession: { sessionId, total_cost_usd, messageCount },
//   budget: null | { budget_usd, setAt, utilization, level },
//   federation: { eventCount, peerCount, totalUsd24h }
// }
//
// Markdown form is also available (--format markdown, the default).

// iter 73 — shared session-loader + memoryRetrieve (was duplicated across 7 scripts).
// ADR-100 / #1748 Issue 3 — CLI_CORE=1 routes to lite cli-core (~2s cold-cache).
import { memoryListAllKeys, memoryRetrieve } from './_sessions.mjs';
// iter 81 — optional git context (sha/branch/isDirty) for snapshot traceability.
import { spawnSync } from 'node:child_process';

const NS = process.env.SUMMARY_NAMESPACE || 'cost-tracking';
const FED_NS = process.env.SUMMARY_FED_NAMESPACE || 'federation-spend';

// iter 81 — git context (optional; graceful degrade outside a repo).
// Makes snapshots traceable — cost-diff can then surface "baseline was
// at sha X, current is at sha Y" without operators having to track it
// out-of-band. All three lookups are best-effort: any failure leaves
// `git: null` in the JSON, which downstream consumers treat as "unknown".
function captureGitContext() {
  function tryGit(args) {
    const r = spawnSync('git', args, {
      stdio: ['ignore', 'pipe', 'pipe'],
      encoding: 'utf-8',
    });
    if (r.status !== 0) return null;
    return (r.stdout || '').trim() || null;
  }
  const sha = tryGit(['rev-parse', 'HEAD']);
  if (!sha) return null;
  const branch = tryGit(['rev-parse', '--abbrev-ref', 'HEAD']);
  const status = tryGit(['status', '--porcelain']);
  return {
    sha,
    shaShort: sha.slice(0, 7),
    branch: branch || null,
    isDirty: status !== null && status.length > 0,
  };
}

function alertLevel(util) {
  if (util >= 1.00) return 'HARD_STOP';
  if (util >= 0.90) return 'CRITICAL';
  if (util >= 0.75) return 'WARNING';
  if (util >= 0.50) return 'INFO';
  return 'OK';
}

function gather() {
  const ctKeys = memoryListAllKeys(NS);
  const sessions = ctKeys.filter((k) => k.startsWith('session-'))
    .map((k) => memoryRetrieve(NS, k)).filter(Boolean);

  const totalUsd = sessions.reduce((s, r) => s + (r.total_cost_usd || 0), 0);
  const byTier = { haiku: 0, sonnet: 0, opus: 0, unknown: 0 };
  const byModel = {};
  // iter 84 — per-token-class aggregation (mirrors iter 83's export.mjs).
  // Surfaces cache_write as a distinct cost driver in summary output.
  const byTokenClass = { input: 0, output: 0, cache_write: 0, cache_read: 0 };
  for (const r of sessions) {
    if (r.byTier) for (const [t, v] of Object.entries(r.byTier)) byTier[t] = (byTier[t] || 0) + v;
    if (r.byModel) {
      for (const [m, slot] of Object.entries(r.byModel)) {
        const agg = byModel[m] || { tier: slot.tier, cost_usd: 0, messages: 0,
          input_tokens: 0, output_tokens: 0, cache_creation_input_tokens: 0, cache_read_input_tokens: 0 };
        agg.cost_usd += slot.cost_usd || 0;
        agg.messages += slot.messages || 0;
        agg.input_tokens += slot.input_tokens || 0;
        agg.output_tokens += slot.output_tokens || 0;
        agg.cache_creation_input_tokens += slot.cache_creation_input_tokens || 0;
        agg.cache_read_input_tokens += slot.cache_read_input_tokens || 0;
        byModel[m] = agg;
        byTokenClass.input       += slot.input_tokens || 0;
        byTokenClass.output      += slot.output_tokens || 0;
        byTokenClass.cache_write += slot.cache_creation_input_tokens || 0;
        byTokenClass.cache_read  += slot.cache_read_input_tokens || 0;
      }
    }
  }

  const topSession = sessions.slice().sort((a, b) => (b.total_cost_usd || 0) - (a.total_cost_usd || 0))[0];

  // Resolve current budget (latest budget-config-<ts>)
  const budgetKey = ctKeys.filter((k) => /^budget-config(-\d+)?$/.test(k)).sort().reverse()[0];
  const budgetCfg = budgetKey ? memoryRetrieve(NS, budgetKey) : null;
  const budget = budgetCfg ? {
    budget_usd: budgetCfg.budget_usd,
    setAt: budgetCfg.setAt,
    spent_usd: totalUsd,
    utilization: budgetCfg.budget_usd > 0 ? totalUsd / budgetCfg.budget_usd : 0,
    level: budgetCfg.budget_usd > 0 ? alertLevel(totalUsd / budgetCfg.budget_usd) : 'OK',
  } : null;

  // Federation aggregate
  const fedKeys = memoryListAllKeys(FED_NS);
  const fedEvents = fedKeys.filter((k) => k.startsWith('fed-spend-'))
    .map((k) => memoryRetrieve(FED_NS, k)).filter(Boolean);
  const peers = new Set(fedEvents.map((e) => e.peerId).filter(Boolean));
  const now = Date.now();
  const day = 24 * 3600 * 1000;
  const totalUsd24h = fedEvents.reduce((s, e) => {
    const ts = e.ts ? new Date(e.ts).getTime() : 0;
    return s + (ts && now - ts < day ? (e.usdSpent || 0) : 0);
  }, 0);

  return {
    exportedAt: new Date().toISOString(),
    // iter 81 — git context for snapshot traceability (null outside a git repo).
    git: captureGitContext(),
    total_cost_usd: totalUsd,
    sessionCount: sessions.length,
    conversationCount: sessions.length,
    byTier,
    byModel,
    // iter 84 — per-token-class summary so consumers can see "X% of spend
    // is cache_write" without re-aggregating byModel themselves.
    byTokenClass,
    topSession: topSession ? {
      sessionId: topSession.sessionId,
      total_cost_usd: topSession.total_cost_usd,
      messageCount: topSession.messageCount,
    } : null,
    budget,
    federation: {
      eventCount: fedEvents.length,
      peerCount: peers.size,
      totalUsd24h,
    },
  };
}

function fmtUsd(n) { return `$${(n || 0).toFixed(4)}`; }

function asMarkdown(s) {
  const lines = [];
  lines.push(`# cost-summary (${s.exportedAt})`);
  if (s.git) {
    const dirty = s.git.isDirty ? ' **(dirty working tree)**' : '';
    lines.push(`_git: \`${s.git.shaShort}\` (${s.git.branch || 'detached HEAD'})${dirty}_`);
  }
  lines.push('');
  lines.push(`| Metric | Value |`);
  lines.push(`|---|---:|`);
  lines.push(`| Total measured spend | **${fmtUsd(s.total_cost_usd)}** |`);
  lines.push(`| Conversations / sessions | ${s.sessionCount} |`);
  if (s.budget) {
    lines.push(`| Budget | ${fmtUsd(s.budget.budget_usd)} |`);
    lines.push(`| Utilization | ${(s.budget.utilization * 100).toFixed(1)}% (${s.budget.level}) |`);
  } else {
    lines.push(`| Budget | unset |`);
  }
  lines.push(`| Federation events | ${s.federation.eventCount} (${s.federation.peerCount} peers, 24h ${fmtUsd(s.federation.totalUsd24h)}) |`);
  lines.push('');
  lines.push(`## By tier`);
  lines.push('');
  lines.push('| Tier | Cost |');
  lines.push('|---|---:|');
  for (const [t, c] of Object.entries(s.byTier)) {
    if (c > 0) lines.push(`| ${t} | ${fmtUsd(c)} |`);
  }
  lines.push('');
  // iter 84 — surface token-class breakdown so cache_write is visible.
  // A 569-output-token, $16 cache-write message used to look like "$16 went
  // to opus" in summary; now it shows "$16 = cache_write tokens" which is
  // what operators need to know to fix the underlying cause.
  if (s.byTokenClass) {
    const totalTokens = Object.values(s.byTokenClass).reduce((a, b) => a + b, 0);
    if (totalTokens > 0) {
      lines.push(`## By token class`);
      lines.push('');
      lines.push('| Class | Tokens | % of tokens |');
      lines.push('|---|---:|---:|');
      for (const cls of ['input', 'output', 'cache_write', 'cache_read']) {
        const n = s.byTokenClass[cls] || 0;
        if (n > 0) {
          const pct = (n / totalTokens) * 100;
          lines.push(`| ${cls} | ${n.toLocaleString()} | ${pct.toFixed(1)}% |`);
        }
      }
      lines.push('');
    }
  }
  if (s.topSession) {
    lines.push(`## Top session`);
    lines.push('');
    lines.push(`- Session \`${(s.topSession.sessionId || '').slice(0, 8)}\`: ${fmtUsd(s.topSession.total_cost_usd)} across ${s.topSession.messageCount} messages`);
  }
  return lines.join('\n');
}

function parseFormat() {
  const args = process.argv.slice(2);
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--format') return args[++i];
  }
  return process.env.SUMMARY_FORMAT || 'markdown';
}

const summary = gather();
if (parseFormat() === 'json') {
  console.log(JSON.stringify(summary, null, 2));
} else {
  console.log(asMarkdown(summary));
}

#!/usr/bin/env node
// test-health-integration — runtime integration test for cost-health.
//
// The iter-75 bug (BUDGET_QUIET=1 silently swallowing HARD_STOP) was a
// classic test-pyramid gap: each subcheck's smoke contract passed
// (anomaly.mjs / burn.mjs / budget.mjs each correctly exit 1 on alert),
// but the COMPOSITE behavior was wrong — cost-health spawned budget.mjs
// with BUDGET_QUIET=1 and budget.mjs returned exit 0 in that mode.
//
// Structural source-grep smoke can detect the pattern in one file, but
// can't validate the cross-script contract. This runtime test exercises
// the composite end-to-end with synthetic fixtures and asserts each
// subcheck's signal correctly reaches cost-health's exit code.
//
// USAGE
//   node scripts/test-health-integration.mjs              # default
//   TEST_HEALTH_KEEP_FIXTURE=1 node scripts/test-health-integration.mjs
//                                                         # leave .swarm intact for debugging
//
// EXIT CODES
//   0  all assertions passed
//   1  at least one assertion failed
//   2  fixture setup error (likely CLI unavailable in CI)

import { spawn, spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';
import { spawnNpxSync } from './_npx.mjs';

const SCRIPTS_DIR = dirname(fileURLToPath(import.meta.url));
const HEALTH = join(SCRIPTS_DIR, 'health.mjs');
const BUDGET = join(SCRIPTS_DIR, 'budget.mjs');
const NS = 'cost-tracking';

let passed = 0, failed = 0;
const failures = [];

function assert(cond, label) {
  if (cond) {
    console.log(`  ✓ ${label}`);
    passed++;
  } else {
    console.log(`  ✗ ${label}`);
    failures.push(label);
    failed++;
  }
}

function memStore(cwd, key, valueObj) {
  const r = spawnNpxSync([
    '-y', '@claude-flow/cli@latest', 'memory', 'store',
    '--namespace', NS, '--key', key,
    '--value', JSON.stringify(valueObj),
  ], {
    cwd,
    stdio: ['ignore', 'pipe', 'pipe'],
    encoding: 'utf-8',
    shell: process.platform === 'win32',
  });
  if (r.status !== 0) {
    const detail = r.error?.message || r.stderr?.trim() || `exit status ${r.status}`;
    console.error(`  → npx memory store failed: ${detail}`);
  }
  return r.status === 0;
}

function memInit(cwd) {
  const r = spawnNpxSync([
    '-y', '@claude-flow/cli@latest', 'memory', 'init',
  ], {
    cwd,
    stdio: ['ignore', 'pipe', 'pipe'],
    encoding: 'utf-8',
    shell: process.platform === 'win32',
  });
  if (r.status !== 0) {
    const detail = r.error?.message || r.stderr?.trim() || `exit status ${r.status}`;
    console.error(`  → npx memory init failed: ${detail}`);
  }
  return r.status === 0;
}

function runHealth(cwd) {
  return new Promise((resolve) => {
    const p = spawn('node', [HEALTH, '--format', 'json'], { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    p.stdout.on('data', (d) => { stdout += d.toString(); });
    p.on('close', (code) => {
      let json = null;
      const m = /\{[\s\S]*\}/.exec(stdout);
      if (m) { try { json = JSON.parse(m[0]); } catch {} }
      resolve({ exitCode: code, json });
    });
  });
}

function runBudget(cwd, subcommand, ...extra) {
  const r = spawnSync('node', [BUDGET, subcommand, ...extra], {
    cwd, stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8',
  });
  return r.status;
}

async function main() {
  const fixture = mkdtempSync(join(tmpdir(), 'cost-health-test-'));
  mkdirSync(join(fixture, '.swarm'), { recursive: true });
  console.log(`# cost-health integration test (fixture: ${fixture})\n`);

  // -----------------------------------------------------------------------
  // Case 1: empty namespace → cost-health overall OK, exit 0.
  // Validates each subcheck handles empty input gracefully (the iter-75 fix
  // CI step is exactly this case, but for a clean cwd).
  // -----------------------------------------------------------------------
  console.log('Case 1: empty namespace');
  {
    // Use a fresh subdir so .swarm doesn't share state with later cases.
    const cwd = join(fixture, 'case-1-empty');
    mkdirSync(join(cwd, '.swarm'), { recursive: true });
    const r = await runHealth(cwd);
    if (!r.json) {
      console.error('  → no JSON output; CLI likely unavailable');
      process.exit(2);
    }
    assert(r.exitCode === 0, 'empty input → exit 0');
    assert(r.json.overall.ok === true, 'empty input → overall.ok === true');
  }

  // -----------------------------------------------------------------------
  // Case 2: budget HARD_STOP → cost-health overall ⚠, exit 1.
  // EXACT REGRESSION TARGET FOR ITER 75. If budget.mjs ever again
  // short-circuits process.exit(1) when BUDGET_QUIET=1 is set, this
  // assertion fails.
  // -----------------------------------------------------------------------
  console.log('Case 2: budget HARD_STOP via BUDGET_QUIET=1');
  {
    const cwd = join(fixture, 'case-2-hardstop');
    mkdirSync(join(cwd, '.swarm'), { recursive: true });
    if (!memInit(cwd)) { console.error('  → fixture initialization failed'); process.exit(2); }
    // 5 sessions × $0.10 = $0.50 spend
    for (let i = 0; i < 5; i++) {
      const ts = new Date(Date.now() - (i + 2) * 86_400_000).toISOString();
      const ok = memStore(cwd, `session-baseline-${i}`, {
        sessionId: `baseline-${i}`, capturedAt: ts,
        total_cost_usd: 0.10, messageCount: 5, byModel: {},
      });
      if (!ok) { console.error('  → fixture write failed'); process.exit(2); }
    }
    // Set $0.20 budget → 250% utilization → HARD_STOP
    if (runBudget(cwd, 'set', '0.20') !== 0) {
      console.error('  → budget set failed');
      process.exit(2);
    }
    const r = await runHealth(cwd);
    if (!r.json) { console.error('  → no JSON output'); process.exit(2); }
    assert(r.exitCode === 1, 'HARD_STOP → exit 1 (iter-75 regression target)');
    assert(r.json.overall.ok === false, 'HARD_STOP → overall.ok === false');
    const budgetCheck = r.json.checks.find((c) => c.name === 'budget');
    assert(budgetCheck && budgetCheck.exitCode === 1,
      'subcheck budget exit code propagated as 1 (was bypassed by BUDGET_QUIET=1 in iter 75)');
  }

  // -----------------------------------------------------------------------
  // Case 3: subcheck skip flag honored.
  // -----------------------------------------------------------------------
  console.log('Case 3: --skip flag honored');
  {
    const cwd = join(fixture, 'case-3-skip');
    mkdirSync(join(cwd, '.swarm'), { recursive: true });
    const p = spawn('node', [HEALTH, '--format', 'json', '--skip', 'burn,projection'], {
      cwd, stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    p.stdout.on('data', (d) => { stdout += d.toString(); });
    const exitCode = await new Promise((res) => p.on('close', res));
    const m = /\{[\s\S]*\}/.exec(stdout);
    const json = m ? JSON.parse(m[0]) : null;
    assert(json && json.checks.length === 2,
      `--skip burn,projection → only 2 checks ran (budget+anomaly), got ${json?.checks?.length}`);
    assert(json && json.config.skipped.includes('burn') && json.config.skipped.includes('projection'),
      'config.skipped reflects CLI args');
  }

  // Cleanup
  if (process.env.TEST_HEALTH_KEEP_FIXTURE !== '1') {
    try {
      rmSync(fixture, { recursive: true, force: true });
    } catch (error) {
      // Windows can retain a transient AgentDB handle after the npx child
      // exits. Fixture cleanup must not hide a completed contract test.
      if (process.platform !== 'win32' || error?.code !== 'EPERM') throw error;
      console.warn(`  → fixture cleanup deferred: ${error.message}`);
    }
  } else {
    console.log(`\n(fixture kept at ${fixture})`);
  }

  console.log(`\n${passed} passed, ${failed} failed`);
  if (failed > 0) {
    console.log('\nFailures:');
    for (const f of failures) console.log(`  - ${f}`);
    process.exit(1);
  }
}

main().catch((e) => {
  console.error('test-health-integration crashed:', e.message || e);
  process.exit(2);
});

#!/usr/bin/env node
// cost-track — auto-capture token usage from a Claude Code session jsonl
// and persist a structured record to the `cost-tracking` AgentDB namespace.
//
// Resolution: by default reads the most-recently-modified session jsonl in
// ~/.claude/projects/<encoded-cwd>/. Override with TRACK_CWD or TRACK_SESSION.
//
// Optional env:
//   TRACK_CWD=<path>          override which project's sessions to scan
//   TRACK_SESSION=<file>      pin to a specific session jsonl
//   TRACK_OUT=<path>          also write the JSON summary to this path
//   TRACK_DRY_RUN=1           skip the memory_store call
//   TRACK_QUIET=1             suppress markdown summary
//   TRACK_NAMESPACE=<name>    override (default: cost-tracking)

import { readFileSync, writeFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';
import { spawnNpxSync } from './_npx.mjs';
// iter 68 — shared PRICING table (was duplicated in counterfactual.mjs too).
import { modelTier, costForUsage } from './_prices.mjs';

const PROJECTS_DIR = join(homedir(), '.claude', 'projects');

function encodeProjectPath(cwd) {
  // #1927: Claude Code encodes an absolute path by replacing path separators
  // AND the Windows drive colon with `-`. So:
  //   POSIX:   /home/user/proj      -> -home-user-proj
  //   Windows: D:\project\Subcloudy -> D--project-Subcloudy   (`:` -> `-`, `\` -> `-`)
  // The old code only replaced `/`, a no-op on Windows paths.
  return cwd.replace(/[/\\:]/g, '-');
}

function findProjectDir(cwd) {
  const candidate = join(PROJECTS_DIR, encodeProjectPath(cwd));
  return existsSync(candidate) ? candidate : null;
}

function findActiveSession(projectDir) {
  const entries = readdirSync(projectDir)
    .filter((f) => f.endsWith('.jsonl'))
    .map((f) => ({ f, mtime: statSync(join(projectDir, f)).mtimeMs }))
    .sort((a, b) => b.mtime - a.mtime);
  return entries[0] ? join(projectDir, entries[0].f) : null;
}

function summarizeSession(jsonlPath) {
  const text = readFileSync(jsonlPath, 'utf-8');
  const lines = text.split('\n').filter(Boolean);
  const byModel = {};
  const byTier = { haiku: 0, sonnet: 0, opus: 0, unknown: 0 };
  let messageCount = 0, totalCost = 0;
  let firstTs = null, lastTs = null;
  let sessionId = null, cwd = null;

  for (const line of lines) {
    let m;
    try { m = JSON.parse(line); } catch { continue; }
    if (!sessionId && m.sessionId) sessionId = m.sessionId;
    if (!cwd && m.cwd) cwd = m.cwd;
    if (m.timestamp) {
      if (!firstTs || m.timestamp < firstTs) firstTs = m.timestamp;
      if (!lastTs || m.timestamp > lastTs) lastTs = m.timestamp;
    }
    if (m.type !== 'assistant' || !m.message?.usage) continue;
    messageCount++;
    const model = m.message.model || 'unknown';
    const tier = modelTier(model);
    const u = m.message.usage;
    const cost = costForUsage(tier, u);
    const slot = byModel[model] || {
      tier,
      input_tokens: 0, output_tokens: 0,
      cache_creation_input_tokens: 0, cache_read_input_tokens: 0,
      messages: 0, cost_usd: 0,
    };
    slot.input_tokens += u.input_tokens || 0;
    slot.output_tokens += u.output_tokens || 0;
    slot.cache_creation_input_tokens += u.cache_creation_input_tokens || 0;
    slot.cache_read_input_tokens += u.cache_read_input_tokens || 0;
    slot.messages++;
    slot.cost_usd += cost;
    byModel[model] = slot;
    byTier[tier] += cost;
    totalCost += cost;
  }

  return {
    sessionId, cwd, startedAt: firstTs, endedAt: lastTs,
    messageCount, byModel, byTier, total_cost_usd: totalCost,
    capturedAt: new Date().toISOString(),
  };
}

function persistToMemory(summary) {
  const ns = process.env.TRACK_NAMESPACE || 'cost-tracking';
  const key = `session-${summary.sessionId || 'unknown'}`;
  // ADR-100 / #1748 Issue 3 — opt into cli-core's lite path with CLI_CORE=1.
  // Cold-cache wall-time drops from ~25s to ~2s. JSON backend instead of
  // SQLite/HNSW; semantic search degrades to substring (fine for cost-track
  // which never invokes search — only store/list/retrieve). See
  // v3/@claude-flow/cli-core/MIGRATION.md.
  const cliPkg = process.env.CLI_CORE === '1'
    ? '@claude-flow/cli-core@alpha'
    : '@claude-flow/cli@latest';
  // spawnSync with explicit args avoids shell-escape pitfalls for the JSON value.
  const r = spawnNpxSync([
    cliPkg, 'memory', 'store',
    '--namespace', ns,
    '--key', key,
    '--value', JSON.stringify(summary),
  ], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf-8', shell: process.platform === 'win32' });
  if (r.status !== 0) {
    return { ok: false, reason: r.stderr?.slice(0, 300) || `exit ${r.status}` };
  }
  return { ok: true, namespace: ns, key };
}

function main() {
  const targetCwd = process.env.TRACK_CWD || process.cwd();
  const projectDir = findProjectDir(targetCwd);
  if (!projectDir) {
    console.error(`cost-track: no Claude Code project dir for cwd=${targetCwd}`);
    console.error(`looked under ${PROJECTS_DIR}/${encodeProjectPath(targetCwd)}`);
    process.exit(2);
  }
  const sessionPath = process.env.TRACK_SESSION || findActiveSession(projectDir);
  if (!sessionPath || !existsSync(sessionPath)) {
    console.error(`cost-track: no session jsonl in ${projectDir}`);
    process.exit(2);
  }

  const summary = summarizeSession(sessionPath);

  if (process.env.TRACK_OUT) {
    writeFileSync(process.env.TRACK_OUT, JSON.stringify(summary, null, 2));
  }

  let storeResult = { ok: false, reason: 'dry-run' };
  if (process.env.TRACK_DRY_RUN !== '1') {
    storeResult = persistToMemory(summary);
  }

  if (process.env.TRACK_QUIET === '1') return;

  console.log(`# cost-track — session ${(summary.sessionId || '').slice(0, 8) || 'unknown'}`);
  console.log('');
  console.log(`| Metric | Value |`);
  console.log(`|---|---:|`);
  console.log(`| Session ID | \`${summary.sessionId}\` |`);
  console.log(`| Project | \`${summary.cwd}\` |`);
  console.log(`| First message | ${summary.startedAt} |`);
  console.log(`| Last message | ${summary.endedAt} |`);
  console.log(`| Assistant messages | ${summary.messageCount} |`);
  console.log(`| **Total cost** | **$${summary.total_cost_usd.toFixed(6)}** |`);
  console.log(`| Persisted | ${storeResult.ok ? `\`${storeResult.namespace}:${storeResult.key}\`` : `**FAILED** (${storeResult.reason})`} |`);
  console.log('');
  console.log('## Per-model breakdown');
  console.log('');
  console.log('| Model | Tier | Messages | Input | Output | Cache write | Cache read | Cost |');
  console.log('|---|---|---:|---:|---:|---:|---:|---:|');
  for (const [m, s] of Object.entries(summary.byModel).sort((a, b) => b[1].cost_usd - a[1].cost_usd)) {
    console.log(`| \`${m}\` | ${s.tier} | ${s.messages} | ${s.input_tokens} | ${s.output_tokens} | ${s.cache_creation_input_tokens} | ${s.cache_read_input_tokens} | $${s.cost_usd.toFixed(6)} |`);
  }
  console.log('');
  console.log('## Per-tier breakdown');
  console.log('');
  console.log('| Tier | Cost |');
  console.log('|---|---:|');
  for (const [t, c] of Object.entries(summary.byTier).sort((a, b) => b[1] - a[1])) {
    if (c > 0) console.log(`| ${t} | $${c.toFixed(6)} |`);
  }
}

main();

#!/usr/bin/env node
// cost-trend — read every docs/benchmarks/runs/*.json and surface drift in
// the gate metrics (winRate, avg latency, total cost). Catches regressions
// the smoke gate misses (gate is binary; trend is a curve).
//
// Usage:
//   node scripts/trend.mjs                     # markdown summary (booster series)
//   TREND_FORMAT=json node scripts/trend.mjs   # machine-readable JSON
//   TREND_LIMIT=10 node scripts/trend.mjs      # consider only the most recent N runs
//   BENCH_NAME=codemod-tier1 node scripts/trend.mjs  # a specific benchmark series
//
// Runs are tagged via summary.benchmark. With no BENCH_NAME, only legacy booster
// runs (untagged or benchmark==="booster") are shown, so other benchmarks
// (e.g. codemod-tier1) never conflate the booster drift curve.

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));
const PLUGIN_ROOT = resolve(HERE, '..');
const RUNS_DIR = join(PLUGIN_ROOT, 'docs', 'benchmarks', 'runs');

function loadRuns() {
  const benchName = process.env.BENCH_NAME;
  const files = readdirSync(RUNS_DIR)
    .filter((f) => f.endsWith('.json') && !f.endsWith('latest.json'))
    .map((f) => ({ f, mtime: statSync(join(RUNS_DIR, f)).mtimeMs }))
    .sort((a, b) => a.mtime - b.mtime);
  const limit = parseInt(process.env.TREND_LIMIT || '50', 10);
  return files.map(({ f }) => {
    try {
      const json = JSON.parse(readFileSync(join(RUNS_DIR, f), 'utf-8'));
      return { file: f, summary: json.summary || {} };
    } catch {
      return null;
    }
  }).filter(Boolean)
    // Keep one benchmark series: BENCH_NAME if set, else legacy booster runs
    // (untagged or benchmark==="booster"). Prevents cross-benchmark conflation.
    .filter((r) => {
      const b = r.summary.benchmark;
      return benchName ? b === benchName : (b === undefined || b === 'booster');
    })
    .slice(-limit);
}

function pct(n) { return `${(n * 100).toFixed(1)}%`; }
function ms(n)  { return `${(n || 0).toFixed(2)}ms`; }
function delta(curr, prev, fmt = (x) => x.toFixed(2), unit = '') {
  if (prev === null || prev === undefined || curr === null || curr === undefined) return '';
  const d = curr - prev;
  const sign = d > 0 ? '+' : '';
  return ` (${sign}${fmt(d)}${unit})`;
}

function main() {
  const runs = loadRuns();
  if (runs.length === 0) {
    console.log('No bench runs found in', RUNS_DIR);
    process.exit(0);
  }

  const series = runs.map((r) => ({
    file: r.file,
    runAt: r.summary.runAt,
    winRate: r.summary.winRate,
    avgLatencyMs: r.summary.avgLatencyMs,
    p99LatencyMs: r.summary.p99LatencyMs,
    overallCorrect: r.summary.overallCorrect,
    escalationRate: r.summary.escalationRate,
    avgConfidence: r.summary.avgConfidence,
    speedupVsLlm: r.summary.speedupVsLlm,
    llmCost: r.summary.llmBaseline?.totalCostUsd,
    anthropicSonnet:
      r.summary.anthropic?.['claude-sonnet-4-6']?.avgLatencyMs || null,
    anthropicOpus:
      r.summary.anthropic?.['claude-opus-4-7']?.avgLatencyMs || null,
  }));

  const first = series[0];
  const last = series[series.length - 1];

  if (process.env.TREND_FORMAT === 'json') {
    console.log(JSON.stringify({ runs: series.length, first, last, series }, null, 2));
    return;
  }

  console.log(`# cost-tracker bench trend (${series.length} runs)`);
  console.log('');
  console.log(`First run: \`${first.file}\` (${first.runAt})`);
  console.log(`Last run:  \`${last.file}\` (${last.runAt})`);
  console.log('');
  console.log('## Drift summary (last vs first)');
  console.log('');
  console.log('| Metric | First | Last | Δ |');
  console.log('|---|---:|---:|---:|');
  if (first.winRate != null && last.winRate != null) {
    console.log(`| Win rate (Tier 1) | ${pct(first.winRate)} | ${pct(last.winRate)} | ${pct(last.winRate - first.winRate)} |`);
  }
  if (first.avgLatencyMs != null && last.avgLatencyMs != null) {
    console.log(`| Avg latency | ${ms(first.avgLatencyMs)} | ${ms(last.avgLatencyMs)} | ${ms(last.avgLatencyMs - first.avgLatencyMs)} |`);
  }
  if (first.p99LatencyMs != null && last.p99LatencyMs != null) {
    console.log(`| p99 latency | ${ms(first.p99LatencyMs)} | ${ms(last.p99LatencyMs)} | ${ms(last.p99LatencyMs - first.p99LatencyMs)} |`);
  }
  if (first.escalationRate != null && last.escalationRate != null) {
    console.log(`| Escalation rate | ${pct(first.escalationRate)} | ${pct(last.escalationRate)} | ${pct(last.escalationRate - first.escalationRate)} |`);
  }
  if (first.speedupVsLlm != null && last.speedupVsLlm != null) {
    console.log(`| Speedup vs Gemini | ${first.speedupVsLlm.toFixed(1)}× | ${last.speedupVsLlm.toFixed(1)}× | ${(last.speedupVsLlm - first.speedupVsLlm).toFixed(1)}× |`);
  }

  console.log('');
  console.log('## Per-run series');
  console.log('');
  console.log('| Run | Win rate | Avg lat | p99 | Escalation | Sonnet 4.6 lat | Opus 4.7 lat |');
  console.log('|---|---:|---:|---:|---:|---:|---:|');
  for (const r of series) {
    const wr = r.winRate != null ? pct(r.winRate) : '—';
    const al = r.avgLatencyMs != null ? ms(r.avgLatencyMs) : '—';
    const p99 = r.p99LatencyMs != null ? ms(r.p99LatencyMs) : '—';
    const er = r.escalationRate != null ? pct(r.escalationRate) : '—';
    const son = r.anthropicSonnet != null ? ms(r.anthropicSonnet) : '—';
    const opu = r.anthropicOpus != null ? ms(r.anthropicOpus) : '—';
    const tag = r.file.replace(/\.json$/, '').slice(0, 19);
    console.log(`| \`${tag}\` | ${wr} | ${al} | ${p99} | ${er} | ${son} | ${opu} |`);
  }

  // Regression flagging
  if (first.winRate != null && last.winRate != null && last.winRate < first.winRate) {
    console.log('');
    console.log(`> ⚠ Regression: win rate dropped ${pct(last.winRate - first.winRate)}`);
  }
  if (first.avgLatencyMs != null && last.avgLatencyMs != null && last.avgLatencyMs > first.avgLatencyMs * 1.5) {
    console.log('');
    console.log(`> ⚠ Regression: avg latency rose ${(last.avgLatencyMs / first.avgLatencyMs).toFixed(2)}× from first run`);
  }
}

main();
